/* 閒聊階梯（大一上；AA_135、AA_136、BB_130；README 在企劃線 docs/story_planning/ladder/）。產生器：tools/ladder/import_ladder.py（不要手改）。來源：claude/cool-heisenberg-o8kuqx 56d5f1ec */
'use strict';
const LADDER={"source": "claude/cool-heisenberg-o8kuqx 56d5f1ec", "characters": {"heroine_01": {"steps": [{"id": "A-L1", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "dayMin": 3, "note": "第二天（民總、筆記、Café）的事件之後；dayMin＝遊戲第幾天（開局那天是第 1 天）", "lines": ["你的筆記是寫在哪裡？"], "choices": [{"t": "「手機。」", "reply": "手機會沒電。……我只是說說。", "mem": "AN_L1_NOTES_PHONE"}, {"t": "「紙本。」", "reply": "好。那考前你借我看一頁，我借你看一頁。公平。", "mem": "AN_L1_NOTES_PAPER"}], "rel": {"fam": 2}}, {"id": "A-L2", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "location": ["linze", "classroom", "library_hall", "library", "campus"], "lines": ["（她翻開手帳，每一頁分成兩欄）左邊寫要做的事，右邊寫為什麼要做。", "沒有理由的那一行，我會劃掉。"], "rel": {"fam": 2}, "mem": "AN_L2_PLANNER"}, {"id": "A-L3", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "lines": ["你住宿舍？我也是。大一女舍。", "我們那棟的規則有十七頁。我讀完了。"], "choices": [{"t": "「十七頁？」", "reply": "其中有三頁在講吹風機。"}, {"t": "「妳全部讀完？」", "reply": "嗯。讀完才知道哪裡寫得不好。……下週樓層會議，我有話要說。"}], "rel": {"fam": 2}, "mem": "AN_L3_DORM", "note": "伏筆：AA_113 事件 3「宿舍的規則」（ev_an_dorm_rules_peishan）；「規則是我們要住的，總要有人讀完」留給那個事件，這裡不說"}, {"id": "A-L4", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "lines": ["我家在台中。高鐵一個小時，比宿舍到公館的公車還準時。", "我媽每個月會找一天和我吃晚餐。……她工作很忙，可是那一天不會改。"], "rel": {"fam": 2, "trust": 1}, "mem": "AN_L4_HOME", "note": "不說媽媽的職業（法官）：大四畢業典禮才第一次對朋友說（AA_113 事件 21）"}, {"id": "A-L5", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [4, 18], "location": ["linze", "classroom", "campus"], "lines": ["憲法課你坐哪？我坐第三排。第一排太近，看不到整個黑板。", "我想聽的是老師沒寫在黑板上的那句。"], "rel": {"fam": 2}, "mem": "AN_L5_CONST", "note": "她的 3D 座位要在前三排（遊戲民總寫「前排的小安」）"}, {"id": "A-L6", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "location": ["noodle", "cafe", "library_hall", "library"], "lines": ["你有沒有一件事，是規則寫得很清楚，但你覺得它沒想到？"], "choices": [{"t": "（舉一個學校或宿舍的例子）", "reply": "好。那你說理由。……嗯，這個我要想一下。（她在手帳右欄寫了一行）", "mem": "AN_L6_RULE_EXAMPLE"}, {"t": "「沒有，我都照規則。」", "reply": "那你是很好的住宿生。……我不是在諷刺你。大概不是。", "mem": "AN_L6_RULE_NONE"}], "rel": {"fam": 2}, "note": "回聲：大一下 ev_an_dorm_appeal 可以加一句「你上學期講的那個例子，我後來還在想。」（AN_L6_RULE_EXAMPLE）"}, {"id": "A-L7", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "lines": ["我跑步。早上六點，繞操場八圈。", "不是為了健康，是因為那個時間沒有人會找我討論事情。"], "rel": {"fam": 2, "comf": 1}, "mem": "AN_L7_RUN"}, {"id": "A-L8", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "week": [8, 18], "lines": ["期中考你準備得怎麼樣？"], "choices": [{"t": "「還好。」", "reply": "「還好」不是一個進度。……好，我不逼你。"}, {"t": "「很慘。」", "reply": "哪一科？……民總的話，第 88 條那段我整理過，你拿去。", "rel": {"trust": 2}}], "rel": {"fam": 2}, "mem": "AN_L8_MIDTERM"}, {"id": "A-L9", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "location": ["library_hall", "library", "linze", "classroom"], "lines": ["我小時候很討厭「因為我說了算」這句話。", "大人講這句，就表示他沒有理由，或懶得講。", "所以我現在講什麼，都會先準備理由。……很累，可是比較公平。"], "rel": {"fam": 2, "trust": 3}, "mem": "AN_L9_REASON"}, {"id": "A-L10", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "week": [14, 18], "lines": ["寒假你回臺北的家，對吧。", "我回台中。我媽說今年要教我做一道菜，她只會那一道。"], "choices": [{"t": "「是什麼菜？」", "reply": "她不說。她說說了我就會先上網查。……她說得對。"}, {"t": "「寒假傳照片來。」", "reply": "好。你也要傳。說好了。", "mem": "AN_L10_PHOTO_PROMISE"}], "rel": {"fam": 2, "comf": 2}, "mem": "AN_L10_WINTER"}], "greet": {"base": ["早。你今天有幾堂？", "我剛從總圖出來。三樓今天很安靜，安靜到有點吵。", "下一堂在 201。走吧，不然後排沒位子。", "我剛剛看到一隻貓坐在傅鐘下面，很像在等下課。", "今天的進度我抄完了。你要的話晚上傳給你。"], "when": [{"time": [6, 8], "location": ["campus"], "t": "（她穿著運動服，剛跑完）……不要看。我還沒換衣服。"}, {"location": ["classroom", "linze"], "time": [8, 12], "t": "第三排還有位子。我幫你留了。……理由：你上次坐太後面。"}, {"location": ["library_hall", "library"], "t": "（她小聲）這裡不能講話。……外面說。"}, {"location": ["noodle"], "t": "這家的排隊規則很清楚：先拿號碼牌，再看菜單。我很喜歡。"}, {"weekday": [5], "time": [17, 24], "t": "週末我回台中。……不是每週。這週是。"}, {"week": [16, 18], "t": "期末了。我的手帳右欄現在只寫一個字：睡。"}]}}, "heroine_03": {"steps": [{"id": "Y-L1", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}, "any": [{"events": ["ev_rain_library_door"]}, {"events": ["ev_noodle_yutong"]}]}, "lines": ["……你是那天總圖門口的。", "嗯。我記得。"], "choices": [{"t": "「傘還好用嗎？」", "reply": "（她想了一下）有傘的話，雨就沒那麼可怕。……這句不是名言，是真的。"}, {"t": "「妳也記得？」", "reply": "我記得很多人。只是很少說。"}], "rel": {"fam": 2}, "linesIf": [{"unless": {"events": ["ev_rain_library_door"]}, "lines": ["……你是阿姨說「很會吃辣」的那個。", "嗯。我記得。"]}], "note": "linesIf：沒遇過總圖門口的雨（只在麵店認識）的玩家，台詞換成這一套，選項照用"}, {"id": "Y-L2", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "location": ["campus", "library_hall", "library"], "lines": ["社會系第一堂課，老師叫我們寫「你從哪裡來」。", "我寫了五個字：公館，汀州路。", "老師說太短。我說那裡很長。"], "rel": {"fam": 2}}, {"id": "Y-L3", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "location": ["noodle", "campus"], "locTime": {"noodle": {"weekday": [2, 4], "time": [20, 20.5]}}, "lines": ["我從小在麵店剝蒜頭。", "一個晚上可以剝兩斤。阿姨說這是我的第一份工作，沒有薪水，有麵吃。"], "choices": [{"t": "「兩斤是多少？」", "reply": "……很多。手會有味道三天。"}, {"t": "「現在還剝嗎？」", "reply": "週二、週四。手的味道是我的行事曆。"}], "rel": {"fam": 2, "comf": 2}, "note": "locTime：在麵店只有週二、四 20:00～20:30（客人少的時候）推進；她的日程週二四 17:30～20:30 在麵店，其他時段在麵店只給短招呼"}, {"id": "Y-L4", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "lines": ["我媽很愛笑。她說我講話比阿姨煮麵還省。", "她說得對。阿姨煮麵很大方。"], "rel": {"fam": 2}, "mem": "YT_MOM_HEARD"}, {"id": "Y-L5", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "location": ["library_hall", "library"], "lines": ["我都坐三樓靠窗。看得到外面有沒有下雨。", "下雨的話，就晚一點走。……我沒帶傘的次數比你想的多。"], "choices": [{"t": "「下次我幫妳看天氣。」", "reply": "嗯。……那你要記得。"}, {"t": "「那把傘妳還是要帶著。」", "reply": "（她笑了一下，很短）好。"}], "rel": {"fam": 2, "comf": 2}, "extraIf": [{"if": {"memory": [{"npc": "heroine_03", "tag": "HELPED"}]}, "lines": ["你那把，我放在櫃台後面。"]}], "note": "extraIf：雨天的總圖門口選「傘給她」（HELPED；flags.rain_umbrella＝give）的玩家，她說完這一層的台詞後多一句"}, {"id": "Y-L6", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "week": [6, 18], "lines": ["我今天在社會學課上講了一句話。", "老師說「很好」。……我回家一路上都在想那兩個字。"], "choices": [{"t": "「妳講了什麼？」", "reply": "我說，大家都說老店靠人情，可是人情要有人記帳。"}, {"t": "「很好就是很好。」", "reply": "嗯。我知道。只是很少有人跟我說。"}], "rel": {"fam": 2, "trust": 2}, "mem": "YT_CLASS_PRAISED"}, {"id": "Y-L7", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "unlessWeekdayTime": {"weekday": [2, 4], "time": [17.5, 20.5]}, "lines": ["我媽每個月要回診一次，都排在週末。", "我陪她去。在醫院等的時候，我會看別人在等什麼。", "……這是社會系的壞習慣。你吃飯了嗎？"], "rel": {"fam": 2, "trust": 3}, "note": "沒有選項：她自己換話題，玩家不追問病況（不寫病名、病情穩定，AA_11 第 0 節）"}, {"id": "Y-L8", "if": {"any": [{"stage": {"npc": "heroine_03", "min": "FRIEND"}}, {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}, "flagNum": {"NOODLE_VISITS": {"min": 3}}}]}, "location": ["noodle", "wenzhou"], "locTime": {"noodle": {"weekday": [2, 4], "time": [20, 20.5]}}, "lines": ["你知道我最喜歡店裡的哪個時間嗎？", "小時候放學，我在店裡等到打烊。阿姨把椅子倒放在桌上，店裡突然很大。", "那十分鐘，沒有人需要我。……現在我八點半就下班了，很少看到。"], "choices": [{"t": "「那哪天陪妳等一次。」", "reply": "……嗯。哪天阿姨要我顧到打烊，我跟你說。"}, {"t": "（什麼都不說，陪她站一下）", "reply": "（她把手邊的一張空椅子倒過來，放到桌上）先練習一下。"}], "rel": {"fam": 2, "comf": 3}, "mem": "YT_TEN_MINUTES", "note": "NOODLE_VISITS：在麵店吃過的次數（沒有這個計數就用 LAWWW-B 現有的麵店造訪紀錄）"}], "greet": {"base": ["嗯。（她點了一下頭）", "今天的湯頭是阿姨說的「剛剛好」。……我也不知道那是什麼意思。", "總圖三樓靠窗，今天有太陽。", "我要去上社會學。……下次說。", "（她把髮圈從手腕拿下來，綁了頭髮，揮了一下手）"], "when": [{"location": ["noodle"], "weekday": [2, 4], "time": [17.5, 20], "t": "（她端著兩碗麵經過）坐那邊。等我一下。……不用等，你先吃。"}, {"location": ["library_hall", "library"], "weather": "rain", "t": "下雨了。……我今天有帶傘。真的。"}, {"location": ["gongguan", "wenzhou"], "t": "這條路我走了十九年。哪一家換了老闆，我都知道。"}, {"weekday": [0, 6], "t": "我等一下要陪我媽。……下週見。"}]}}, "heroine_02": {"steps": [{"id": "Z-L1", "if": {"stage": {"npc": "heroine_02", "min": "ACQUAINTANCE"}}, "unlessWorking": true, "lines": ["你是那個……第一次來就問 Wi-Fi 密碼的人。", "不是在說你壞話。大家第一句都是這個。"], "choices": [{"t": "「密碼很難記。」", "reply": "密碼是店名加開店那年。老闆很懷舊。"}, {"t": "「妳記得每個人第一次說什麼？」", "reply": "……沒有每個人。只是有些人比較好記。"}], "rel": {"fam": 2}}, {"id": "Z-L2", "if": {"stage": {"npc": "heroine_02", "min": "ACQUAINTANCE"}}, "unlessWorking": true, "lines": ["法律系是不是每天都在背東西？", "外文系也背。單字、詩、別人的名字。"], "choices": [{"t": "「我們背條文，你們背詩。」", "reply": "詩比較短。可是比較難懂。"}, {"t": "「我比較怕考申論。」", "reply": "申論就是寫很長的「我覺得」。我們也是。"}], "rel": {"fam": 2}}, {"id": "Z-L3", "if": {"stage": {"npc": "heroine_02", "min": "ACQUAINTANCE"}}, "unlessWorking": true, "lines": ["週五的經原，我坐在你後面兩排。……你沒發現吧。", "經原我是第二次修。第一次期中考完，我就沒去了。", "……不是因為難。是那學期很亂。"], "linesIf": [{"if": {"events": ["ev_zhiruo_ge_group"]}, "lines": ["經原我是第二次修。第一次期中考完，我就沒去了。", "……不是因為難。是那學期很亂。"]}], "choices": [{"t": "「這次我盯著妳，不讓妳翹。」", "reply": "你很有自信。我先記下來。"}, {"t": "「那學期怎麼了？」", "reply": "沒怎麼了。就是亂。……下一題。", "mem": "ZR_ASKED_MESSY"}], "rel": {"fam": 3}, "note": "2026-10-16 BB-B：原本 if 要 ev_zhiruo_ge_group（Y1S1 一次性的 auto 事件，錯過就永遠卡在 Z-L3）→ 拿掉；分組過的玩家（linesIf）不說「坐你後面兩排」那句；選項改成兩種玩家都說得通"}, {"id": "Z-L4", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "lines": ["你知道嗎，店裡最常被點的不是咖啡，是「跟上次一樣」。", "我最喜歡聽人家這樣說。"], "choices": [{"t": "「因為妳都記得。」", "reply": "……那是工作。（她低頭擦杯子）"}, {"t": "「那我下次也說這句。」", "reply": "你要先有「上次」。"}], "rel": {"fam": 2, "comf": 2}}, {"id": "Z-L5", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "location": ["campus", "putong", "boya"], "weekday": [2, 4], "lines": ["外文系的教室窗戶看出去是椰子樹。我上課常常在數它們。", "數到第七棵就下課了。"], "choices": [{"t": "「法律系的窗戶看出去是另一棟法律系。」", "reply": "……那你們好辛苦。"}, {"t": "「妳在數椰子樹的時候想什麼？」", "reply": "想這一幕如果是電影，要用多長的鏡頭。"}], "rel": {"fam": 2}}, {"id": "Z-L6", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "lines": ["我家在台中開影印店。一張一塊。", "小時候我在店裡看別人印的東西長大：講義、論文、尋狗啟事。"], "choices": [{"t": "「尋狗啟事？」", "reply": "印了三百張。第二天狗自己回家了。老闆娘——我媽——說這是她印過最好的一份。"}, {"t": "「那妳很會看別人在忙什麼。」", "reply": "……你這樣說，好像我是偷看的人。是啦。"}], "rel": {"fam": 3, "trust": 2}, "mem": "ZR_HOMETOWN"}, {"id": "Z-L7", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "location": ["cafe", "wenzhou"], "time": [19, 24], "unlessWorking": true, "lines": ["你有沒有看過一部電影，看完不想跟任何人講？", "不是不好看。是太好看，講了就會變少。"], "choices": [{"t": "「有。」", "reply": "那不要告訴我是哪一部。"}, {"t": "「沒有。我看完都想講。」", "reply": "那你很幸福。……我是說真的。"}], "rel": {"fam": 2, "comf": 2}}, {"id": "Z-L8", "if": {"any": [{"stage": {"npc": "heroine_02", "min": "FRIEND"}}, {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}, "flagNum": {"CAFE_VISITS": {"min": 4}}}]}, "unlessWorking": true, "lines": ["我發現你點東西的時候，都會先看我一眼，再看菜單。", "……我不是在講什麼。只是發現。"], "choices": [{"t": "「因為妳會給建議。」", "reply": "我給的建議都是今天比較好喝的。不是我比較喜歡的。"}, {"t": "「我沒發現。」", "reply": "嗯。所以是我發現。"}], "rel": {"fam": 2, "comf": 3}}], "greet": {"base": ["嗨。（她推一下眼鏡）", "今天的豆子還可以。", "你又來了。……不是不歡迎。", "外面要下雨了。你沒帶傘吧。", "（她在吧檯後面點了一下頭）"], "when": [{"working": true, "t": "（她在吧檯後面點了一下頭，手沒停）"}, {"location": ["cafe"], "time": [22, 24], "t": "要打烊了。……你可以坐到我擦完這張桌子。"}, {"location": ["campus", "putong", "boya"], "t": "在學校遇到你好奇怪。好像在店外面看到菜單。"}, {"weekday": [0, 6], "t": "週末我不上班。所以我現在不是店員。"}]}}, "heroine_04": {"steps": [{"id": "Q-L1", "if": {"stage": {"npc": "heroine_04", "min": "ACQUAINTANCE"}}, "time": [14, 24], "lines": ["欸不是，阿凱說你是他室友。", "他說你很安靜。安靜很好。我們社團缺安靜的人。"], "choices": [{"t": "「我不會彈吉他。」", "reply": "我也不會。我是去聽的。……騙你的，我會。"}, {"t": "「阿凱怎麼形容我的？」", "reply": "「他會在我打遊戲的時候講法律」。"}], "rel": {"fam": 2}}, {"id": "Q-L2", "if": {"stage": {"npc": "heroine_04", "min": "ACQUAINTANCE"}}, "time": [14, 24], "lines": ["你知道資工系館晚上幾點會熄燈嗎？", "十二點。可是三樓的門禁卡我有。不要告訴別人。這是祕密。"], "choices": [{"t": "「法律系館八點就鎖了。」", "reply": "那你們很慘。我同情你們。"}, {"t": "「半夜在系館做什麼？」", "reply": "寫程式。晚上的系館很安靜，只剩伺服器在叫。這不是比喻。"}], "rel": {"fam": 2}}, {"id": "Q-L3", "if": {"stage": {"npc": "heroine_04", "min": "ACQUAINTANCE"}}, "time": [14, 24], "skipIf": {"memory": [{"npc": "heroine_04", "tag": "INVITED_CLUB"}]}, "lines": ["你看過我手指嗎？這裡，都是繭。", "按吉他弦按出來的。新手按到痛，就代表有在按。"], "linesIf": [{"if": {"events": ["ev_ziqing_club"]}, "lines": ["你上次在社課的時候，手指按很用力。", "新手都這樣。按到痛，就代表你有在按。"]}], "choices": [{"t": "「會痛很正常嗎？」", "reply": "正常。痛兩週。之後就不痛了。很像人生。……我亂講的。"}, {"t": "「我的手指不行。」", "reply": "每個人一開始都不行。這不是安慰，是統計。"}], "rel": {"fam": 2}, "note": "2026-10-16 BB-B（AA-B 指出）：原本 if 用 notMemory INVITED_CLUB＋要 ev_ziqing_club，有 INVITED_CLUB 或沒去過社課的玩家會永遠卡在 Q-L3 → 有 INVITED_CLUB（聽過 SMALLTALK「手指好了沒」）的用 skipIf 直接算過；沒去過社課的照一般 lines，去過的用 linesIf；選項改成兩種都說得通"}, {"id": "Q-L4", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "lines": ["我早上不起床。不是懶。我晚上的腦比較好用。", "你早八？……我為你默哀。"], "choices": [{"t": "「我也是晚上比較清醒。」", "reply": "好。那你是自己人。"}, {"t": "「早八其實還好。」", "reply": "你說謊的時候會看旁邊。我看到了。"}], "rel": {"fam": 2, "comf": 2}}, {"id": "Q-L5", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "lines": ["我在做一個遊戲。主角是一隻貓。", "牠一直在找插座。……不要笑。這是很嚴肅的遊戲。"], "choices": [{"t": "「為什麼是貓？」", "reply": "因為貓不用解釋自己在幹嘛。"}, {"t": "「我沒有笑。」", "reply": "你有。你嘴角在笑。可是我接受。"}], "rel": {"fam": 3}, "mem": "ZQ_GAME_HEARD"}, {"id": "Q-L6", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "location": ["gongguan", "wancai"], "time": [19, 24], "lines": ["系上排名第一的人，缺席率也是第一。你猜是誰。", "……對。所以教授看到我都很頭痛。"], "choices": [{"t": "「成績好就好了吧？」", "reply": "教授不這樣想。我家也不這樣想。……好，下一題。"}, {"t": "「妳不去上課在做什麼？」", "reply": "做遊戲。睡覺。做遊戲。這是順序。"}], "rel": {"fam": 2}}, {"id": "Q-L7", "if": {"any": [{"stage": {"npc": "heroine_04", "min": "FRIEND"}}, {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}, "memory": [{"npc": "heroine_04", "tag": "PLAYTESTED"}]}]}, "time": [14, 24], "lines": ["你玩我的遊戲的時候，卡在第二關卡了很久。", "我看到了。我在旁邊。我沒說話。這很難得。"], "linesIf": [{"unless": {"memory": [{"npc": "heroine_04", "tag": "PLAYTESTED"}]}, "lines": ["你還沒玩過我的遊戲。下次你來測。", "我會在旁邊看你卡在哪裡。不說話。這很難得。"]}], "choices": [{"t": "「我很容易卡關。」", "reply": "那很好。會卡關的人，才看得出哪裡做壞了。"}, {"t": "「妳一直看，我會緊張。」", "reply": "緊張是好事。代表你在乎。我是說在乎遊戲。"}], "rel": {"fam": 2, "trust": 2}, "note": "2026-10-16 BB-B：沒有 PLAYTESTED、但已經 FRIEND 的玩家用 linesIf 換整套開場（原本寫在 note）；選項改成兩種都說得通"}, {"id": "Q-L8", "if": {"stage": {"npc": "heroine_04", "min": "FRIEND"}}, "time": [14, 24], "lines": ["欸不是，你下次社課要來。不是因為缺人。", "是因為你在的時候，阿凱比較不會遲到。"], "choices": [{"t": "「這是問句嗎？」", "reply": "不是。（她笑了）"}, {"t": "「好，我去。」", "reply": "我記下來了。你不能反悔。這不是問句。"}], "rel": {"fam": 2, "comf": 2}}], "greet": {"base": ["欸。", "我剛起床。不要跟我講話。……好啦，講一句。", "滷味十點後半價。只是告訴你。", "（她把耳機拿下來一邊）怎樣？", "你又要去上課？……法律系好勤勞。"], "when": [{"time": [14, 16], "t": "早。……對，我的早上是下午兩點。"}, {"location": ["wancai"], "weekday": [1, 3], "time": [18.5, 21], "t": "社課快開始了。你今天有要按到手痛嗎？"}, {"location": ["gongguan"], "time": [22, 24], "t": "這個時間在公館遇到你，你墮落了。歡迎。"}, {"weekday": [0, 6], "t": "週末不要跟我講課業。只能講遊戲。"}]}}, "heroine_05": {"friendOnly": true, "steps": [{"id": "S-L1", "if": {"stage": {"npc": "heroine_05", "min": "ACQUAINTANCE"}}, "location": ["library", "campus"], "time": [9, 17], "weekday": [1, 2, 3, 4, 5], "lines": ["學弟。兩件事。", "一，總圖二樓的飲水機壞了，去三樓裝。二，沒有二。"], "choices": [{"t": "「謝謝學姊。」", "reply": "不用謝。我只是不想看到大家拿空杯子走來走去。"}, {"t": "「為什麼說兩件事？」", "reply": "本來有兩件。說到一半忘了。……不要跟別人說。"}], "rel": {"fam": 2}}, {"id": "S-L2", "if": {"stage": {"npc": "heroine_05", "min": "ACQUAINTANCE"}}, "lines": ["你們民總現在上到哪？", "……第幾章不重要。重要的是你看不看得懂那一章在問什麼。"], "choices": [{"t": "「我還在背定義。」", "reply": "定義先背。可是背完要問自己：這個定義在防什麼？", "rel": {"resp": 2}}, {"t": "「我還在找問題在哪。」", "reply": "那你已經比背定義的人快一步。", "rel": {"resp": 2}}], "rel": {"fam": 2}}, {"id": "S-L3", "if": {"stage": {"npc": "heroine_05", "min": "ACQUAINTANCE"}, "flags": ["lawclub"], "events": ["ev_studygroup_wed"]}, "skipIf": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}, "notEvents": ["ev_studygroup_wed"]}, "note": "2026-10-16 BB-B：沒去週三讀書會（沒加法服）的玩家原本會永遠卡在 S-L3 → 到 FAMILIAR 還沒去過就 skipIf 直接算過", "lines": ["你第一次來讀書會，坐在門邊。", "新人都坐門邊。方便逃走。我第一年也是。"], "choices": [{"t": "「學姊也想過逃走？」", "reply": "每個週三。……可是我沒有逃。所以現在我是社長。這不是勵志故事，是警告。"}, {"t": "「門邊比較涼。」", "reply": "好理由。可是下次往前坐一排。"}], "rel": {"fam": 3, "comf": 2}}, {"id": "S-L4", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}}, "lines": ["你知道我保溫瓶裡裝什麼嗎？", "咖啡。三倍濃。不要學。"], "choices": [{"t": "「三倍？」", "reply": "一倍給上課，一倍給法服，一倍給剩下的。"}, {"t": "「學姊睡得夠嗎？」", "reply": "……這不是你該問的問題。可是謝謝。", "mem": "SIS_ASKED_SLEEP"}], "rel": {"fam": 2}}, {"id": "S-L5", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}}, "lines": ["我爸媽都是公務員。從小他們就說，考上司法官很好。", "我也覺得很好。……我是說，我一直都這樣覺得。"], "choices": [{"t": "「那學姊想當司法官嗎？」", "reply": "三件事。一，想。二，大概。三，下一題。"}, {"t": "「妳說『一直都』。」", "reply": "你很會聽重點。這是誇獎。也是警告。"}], "rel": {"fam": 2, "trust": 3}, "mem": "SIS_PARENTS_HEARD"}, {"id": "S-L6", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}, "flags": ["lawclub"]}, "location": ["wancai"], "weekday": [3], "time": [20.5, 23], "skipIf": {"notFlags": ["lawclub"]}, "lines": ["今天那題，你回答得不對。", "可是你回答的方式是對的：先說你不確定的地方。"], "choices": [{"t": "「那對的答案是什麼？」", "reply": "回去查。查到了明天告訴我。不是考你，是我也想再確認一次。", "rel": {"resp": 3}}, {"t": "「我很怕講錯。」", "reply": "法服最不怕的就是講錯。最怕的是講錯了不說。", "rel": {"resp": 3}}], "rel": {"fam": 2}, "note": "週三晚上法服讀書會之後（萬才館）"}, {"id": "S-L7", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "lines": ["學弟，你覺得公法無聊嗎？", "大家都說公法無聊。我覺得是因為大家還沒遇過被政府擋住的事。"], "choices": [{"t": "「我還沒遇過。」", "reply": "希望你一直都不用遇到。……可是如果遇到，記得來找法服。"}, {"t": "「我覺得不無聊。」", "reply": "好。你是第三個這樣說的一年級。我記住了。", "mem": "SIS_PUBLIC_LAW_FAN"}], "rel": {"fam": 2}}, {"id": "S-L8", "if": {"stage": {"npc": "heroine_05", "min": "FRIEND"}}, "lines": ["三件事。", "一，你最近有睡飽。我看得出來。二，期中考前不要換位子。三……", "（她想了一下）三，沒事。今天到這裡。"], "choices": [{"t": "「第三件是什麼？」", "reply": "說了沒事就是沒事。（她把保溫瓶握緊了一點）"}, {"t": "「學姊也要睡飽。」", "reply": "……一，知道了。"}], "rel": {"fam": 2, "comf": 3}}], "greet": {"base": ["學弟。", "一件事：吃飯了沒。", "（她舉了一下保溫瓶）", "總圖今天很冷，帶外套。", "讀書會不要遲到。"], "when": [{"location": ["library"], "t": "（小聲）學弟。三樓有位子。"}, {"weekday": [3], "time": [17, 19.5], "t": "今天週三。七點，萬才館。"}, {"weekday": [6], "time": [8, 12.5], "t": "今天法服值班。不是叫你來，是告訴你我在哪。", "note": "單週週六上午（法服方案 A）；雙週不說"}, {"time": [22, 24], "t": "這麼晚了。一件事：回去睡。"}]}}, "classmate_peishan": {"steps": [{"id": "P-L1", "if": {"stage": {"npc": "classmate_peishan", "min": "ACQUAINTANCE"}}, "lines": ["我可以問一個奇怪的問題嗎？", "你覺得法律系的人，看起來有一種樣子嗎？"], "choices": [{"t": "「有，看起來都很累。」", "reply": "……我也是嗎？不要回答。"}, {"t": "「沒有，大家都不一樣。」", "reply": "那很好。我本來擔心我看起來不像。"}], "rel": {"fam": 2}}, {"id": "P-L2", "if": {"stage": {"npc": "classmate_peishan", "min": "ACQUAINTANCE"}}, "lines": ["我爸媽在桃園開早餐店。", "所以我早上六點會自己醒來。不是因為認真，是身體記得要煎蛋。"], "choices": [{"t": "「好羨慕。」", "reply": "你不會羨慕的。週末四點半起床的那種。"}, {"t": "「那妳早八都不會遲到。」", "reply": "不會遲到。可是會睡著。"}], "rel": {"fam": 2}, "mem": "PS_FAMILY_SHOP"}, {"id": "P-L3", "if": {"stage": {"npc": "classmate_peishan", "min": "ACQUAINTANCE"}, "events": ["ev_studygroup_wed"], "memory": [{"npc": "classmate_peishan", "tag": "FIRST_MET"}]}, "skipIf": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}, "notEvents": ["ev_studygroup_wed"]}, "note": "2026-10-16 BB-B：沒去週三讀書會的玩家原本會永遠卡在 P-L3 → 到 FAMILIAR 還沒去過就 skipIf 直接算過", "lines": ["讀書會的學姊講話好快。我抄到一半就跟不上了。", "你有抄到嗎？"], "choices": [{"t": "「我抄到一半。」", "reply": "我們拼起來，就是一整份了。", "mem": "PS_NOTES_SHARED"}, {"t": "「我沒抄，我在聽。」", "reply": "……我也想變成那樣的人。"}], "rel": {"fam": 3}}, {"id": "P-L4", "if": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}}, "lines": ["我今天去旁聽哲學系的課。", "老師問：如果一條規則每個人都遵守，結果很糟，那還要遵守嗎？……我想了一整節。"], "choices": [{"t": "「法律也會問這個。」", "reply": "真的嗎？那我是不是應該更喜歡法律一點？"}, {"t": "「妳的答案是什麼？」", "reply": "還沒有。我想先聽完下週的課。"}], "rel": {"fam": 2, "trust": 2}}, {"id": "P-L5", "if": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}}, "lines": ["我可以再問一個奇怪的問題嗎？", "你覺得考試考得好的人，就是懂的人嗎？"], "choices": [{"t": "「不一定。」", "reply": "我也覺得。可是我還是很想考得好。好矛盾。"}, {"t": "「至少比較懂考試。」", "reply": "哈。這個答案好誠實。"}], "rel": {"fam": 2, "comf": 2}}, {"id": "P-L6", "if": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}}, "lines": ["桃園回台北的客運，過了林口就會開始塞車。", "我都在塞車的時候背法條。背到交流道，剛好一頁。"], "choices": [{"t": "「這是很好的計時器。」", "reply": "對吧。不塞車的時候我反而背不完。"}, {"t": "「我搭捷運都在睡覺。」", "reply": "臺北人好幸福。"}], "rel": {"fam": 2}}, {"id": "P-L7", "if": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}}, "lines": ["我發現我上課抄最多的地方，都是老師講故事的時候。", "條文的地方，我反而抄很少。……這樣是不是不對？"], "choices": [{"t": "「故事比較好記。」", "reply": "嗯。可是考試不考故事。（她笑了一下）"}, {"t": "「條文課本都有，故事沒有。」", "reply": "……你說得對。我好像沒有那麼糟。", "mem": "PS_REASSURED"}], "rel": {"fam": 2, "trust": 2}}, {"id": "P-L8", "if": {"stage": {"npc": "classmate_peishan", "min": "FRIEND"}}, "lines": ["謝謝你都會認真回答我的奇怪問題。", "大部分的人會說「妳想太多」。"], "choices": [{"t": "「妳的問題都不奇怪。」", "reply": "……有一點奇怪。可是謝謝。"}, {"t": "「我也常想太多。」", "reply": "那我們是想太多的同盟。"}], "rel": {"fam": 2, "comf": 3}}], "greet": {"base": ["嗨！", "我今天沒有奇怪的問題。……騙你的，明天再問。", "你吃早餐了嗎？", "我要去哲學系。下次聊！", "（她揮了揮手上的筆記）"], "when": [{"time": [6, 9], "t": "早！我已經醒三個小時了。早餐店的小孩都這樣。"}, {"location": ["wancai"], "weekday": [3], "time": [18, 19.5], "t": "讀書會快開始了。你今天要坐門邊嗎？"}, {"location": ["library"], "t": "（小聲）嗨。我在抄學姊的筆記。"}, {"weekday": [5], "time": [17, 24], "t": "週五了。我要搭客運回桃園。下週見！"}]}}, "kexin": {"context": "date", "steps": [{"id": "K-L1", "if": {"flags": ["dating_kexin"]}, "lines": ["政大的山，我還在跟它不熟。", "每天上去的時候都覺得它在考我。下來的時候它說：及格。"], "choices": [{"t": "「我們這邊只有平地。」", "reply": "那你們很好命。……可是你們沒有風景。"}, {"t": "「下次我陪妳爬一次。」", "reply": "好。不准中途停下來拍照。……好啦，可以拍一張。"}]}, {"id": "K-L2", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "lines": ["（她摸了一下耳朵上的小長頸鹿）我的耳環只戴一邊，而且每天不一樣。", "另一邊空著，是留給還沒想到的那一個耳環。……不要問長什麼樣子，我也還沒想到。"], "choices": [{"t": "「下次我幫妳挑一個。」", "reply": "好。可是要很奇怪的。不奇怪我不戴。"}, {"t": "「今天這隻很好看。」", "reply": "我知道。我只是想聽你說。"}], "mem": "KX_EARRING_STORY"}, {"id": "K-L3", "if": {"flags": ["dating_kexin"]}, "lines": ["政大法律系的同學，第一週就分好讀書會了。", "我和予樂一組。她負責講話，我負責讓她不要講太久。", "還有一個叫邵鈞的，他什麼都要查出處。……我覺得我們會變成好朋友。"]}, {"id": "K-L4", "if": {"flags": ["dating_kexin"]}, "week": [4, 18], "lines": ["我們民總老師今天問：人什麼時候開始算是人？", "全班吵了一節。我站「出生」。你們呢？"], "choices": [{"t": "（說你們老師怎麼講）", "reply": "……好，那我們兩個學校意見一致。好無聊。（她笑）"}, {"t": "「我們還沒教到。」", "reply": "那你先想。下次見面你要給我答案，不准查課本。"}]}, {"id": "K-L5", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "lines": ["你知道我最喜歡我們見面的哪個時候嗎？", "不是見到的時候。是要分開、還沒分開的那五分鐘。", "因為那五分鐘我們都在想，下次要說什麼。"], "choices": [{"t": "「那下次多留五分鐘。」", "reply": "不行。多留就會變成十分鐘，十分鐘就會錯過公車。……我算過了。"}, {"t": "（不說話，陪她等公車）", "reply": "（她靠在你肩上一下）好。這次的五分鐘很好。"}], "rel": {"comf": 3}, "mem": "KX_FIVE_MINUTES"}, {"id": "K-L6", "if": {"flags": ["dating_kexin"]}, "week": [7, 18], "dateOnly": "video", "lines": ["（她把手機立在書堆旁邊，只看得到她的額頭）不要講話。我們各自念。", "（二十分鐘後）……你翻頁的聲音好大。", "我不是在抱怨。是我聽得到，所以知道你還在。"], "note": "視訊一起讀書；精力照一般讀書"}, {"id": "K-L7", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "lines": ["予樂問我，你是什麼樣的人。", "我說：他會在我講完話以後，等兩秒才回答。她說這樣很好。我說我知道。"], "choices": [{"t": "「我在想要怎麼回答。」", "reply": "對。所以我說很好。"}, {"t": "「那妳怎麼介紹妳自己？」", "reply": "我說：我會假設很多事。她說她早就知道了。"}], "rel": {"trust": 2}}, {"id": "K-L8", "if": {"flags": ["dating_kexin"]}, "week": [14, 18], "lines": ["這學期快結束了。", "我本來以為不同學校會很難。……結果只是很遠，不是很難。", "假設——算了，今天不假設。今天就是今天。"], "mem": "KX_TERM1_DONE"}], "greet": null}}, "terms": {"heroine_01": "Y1S1", "heroine_03": "Y1S1", "heroine_02": "Y1S1", "heroine_04": "Y1S1", "heroine_05": "Y1S1", "classmate_peishan": "Y1S1", "kexin": "Y1S1"}, "byTerm": {"Y1S2": {"heroine_01": {"steps": [{"id": "A2-L1", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [1, 18], "lines": ["寒假我回台中。我媽教了我一道菜。", "番茄炒蛋。她說她只會這一道。……我學了三天。"], "choices": [{"t": "「學會了嗎？」", "reply": "第三天學會了。理由：前兩天的蛋都太老。"}, {"t": "「下次做給我吃。」", "reply": "……等我做到第五次。第五次才算會。", "rel": {"comf": 1}}], "rel": {"fam": 2}, "mem": "AN2_TOMATO_EGG", "extraIf": [{"if": {"memory": [{"npc": "heroine_01", "tag": "AN_L10_PHOTO_PROMISE"}]}, "lines": ["你寒假傳的照片，我都看了。回了「收到」。……我知道，很冷淡。"]}], "note": "承接大一上 A-L10（寒假學一道菜）；沒聽過 A-L10 的玩家也說得通。extraIf：說好互傳照片的玩家多一句"}, {"id": "A2-L2", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [2, 18], "lines": ["我早上七點有日文課。不是學分，我自己報的。", "動詞變化有很多規則，也有很多例外。……很像法律。"], "choices": [{"t": "「為什麼學日文？」", "reply": "……理由還在寫。寫好了再告訴你。"}, {"t": "「七點也太早。」", "reply": "七點的教室，只有想學的人。我喜歡。"}], "rel": {"fam": 2}, "mem": "AN2_JAPANESE", "note": "交接包 v2 第 2 週的背景（總圖門口遇到剛下課、念動詞變化的她）。**不說為什麼學**：大三交換日本的伏筆，這裡不講"}, {"id": "A2-L3", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [3, 18], "location": ["campus"], "lines": ["（她拿手機對著一叢杜鵑花）……我要每年在同一個位置拍一張。", "四年，四張。今天是第一張。"], "choices": [{"t": "「我幫妳拍？」", "reply": "不用。要我自己拍。理由：同一個人拍，才比得出來。"}, {"t": "「為什麼是這裡？」", "reply": "看得到傅鐘。四年以後，它還會在這裡。"}], "rel": {"fam": 2}, "mem": "AN2_AZALEA", "linesIf": [{"week": [7, 18], "lines": ["杜鵑花謝了。……三月的時候，我在這裡拍了一張。", "每年同一個位置。四年，四張。今年是第一張。"]}], "note": "交接包 v2 第 3 週（杜鵑花季）。第 7 週以後才推進的玩家：花謝了，改說「三月拍了」（linesIf），不卡關"}, {"id": "A2-L4", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [7, 18], "lines": ["我室友的申訴，過了一半。點數減了一點。", "她請我吃了一碗麵。她說我寫的理由太多。……可是她贏了一半。"], "choices": [{"t": "「理由多不是壞事。」", "reply": "……嗯。可是要讓人看得完。這是我這次學到的。"}, {"t": "「她說得對。」", "reply": "……你站她那邊。好。下次你當她的律師。"}], "rel": {"fam": 2, "trust": 1}, "linesIf": [{"if": {"events": ["ev_an_dorm_appeal"]}, "lines": ["上次你幫我讀的申訴，結果出來了。點數減了一點。", "室友請我吃了一碗麵。她說我寫的理由太多。……可是她贏了一半。"]}], "note": "以安新 5（ev_an_dorm_appeal，第 5 週，結果第 7 週）。沒遇到事件的玩家照一般台詞（她自己講結果）；遇到的玩家 linesIf 改成「你幫我讀的」"}, {"id": "A2-L5", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "week": [9, 18], "lines": ["期中考完，我的手帳右欄寫：還可以。", "……「還可以」不是一個進度。我自己說過的。"], "choices": [{"t": "「那是什麼？」", "reply": "是「我盡力了，可是不想說」。……你不准笑。"}, {"t": "「我也還可以。」", "reply": "……那我們兩個都不是進度。下週一起把它變成進度。", "rel": {"comf": 1}}], "rel": {"fam": 2, "comf": 1}, "linesIf": [{"unless": {"memory": [{"npc": "heroine_01", "tag": "AN_L8_MIDTERM"}]}, "lines": ["期中考完，我的手帳右欄寫：還可以。", "……「還可以」不是一個進度。可是我今天只想寫這三個字。"]}], "note": "回聲大一上 A-L8（「還好」不是一個進度）；沒聽過的玩家用 linesIf 那一套"}, {"id": "A2-L6", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "week": [12, 18], "lines": ["公法讀書會，每人十分鐘。小語說可以吃東西。", "……我同意了。理由：十分鐘很餓。"], "choices": [{"t": "「妳們和好了？」", "reply": "我們沒有吵。是在辯論。……好，有一點吵。"}, {"t": "「我可以去嗎？」", "reply": "可以。週四晚上八點。十分鐘你要講什麼，先想好。"}], "rel": {"fam": 2}, "linesIf": [{"if": {"events": ["ev_an_study_group"]}, "lines": ["你來過讀書會了。你的十分鐘，講了十二分鐘。", "……我沒有在計時。我有。"]}], "note": "以安新 7（第 11～12 週：和小語吵架 ev_an_yu_argument，然後開了公法讀書會）。讀書會的事件 id 照 LAWWW-B 實作時的名稱換（這裡先寫 ev_an_study_group）；沒去過的玩家照一般台詞"}, {"id": "A2-L7", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "lines": ["我媽說，我講話越來越像她。", "先講結論，然後不太讓別人插嘴。……後面那個我在改。"], "choices": [{"t": "「哪裡像？」", "reply": "……剛剛那句。先講結論。"}, {"t": "「像也沒關係吧。」", "reply": "……你又不認識她。……好，我收下。", "rel": {"trust": 1}}], "rel": {"fam": 2, "trust": 2}, "mem": "AN2_LIKE_MOM", "note": "**不說媽媽的職業**（法官；AA_113：大四畢業典禮才第一次對朋友說）。只講說話方式"}, {"id": "A2-L8", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "week": [15, 18], "lines": ["暑假我七月底回台中兩週。", "剩下的時間在臺北。……我還沒排。第一次沒排。"], "choices": [{"t": "「要不要一起排？」", "reply": "……好。你排第一版。我改。", "rel": {"comf": 2}}, {"t": "「沒排也很好。」", "reply": "……嗯。我在練習。"}], "rel": {"fam": 2, "comf": 1}, "mem": "AN2_SUMMER", "note": "AA_128：以安暑假 7/18～7/31 在台中"}], "greet": {"base": ["早。……我剛下日文課。腦子裡都是動詞。", "這學期的憲法，老師講得比較快。我抄得比較慢。", "我剛從總圖出來。二樓的長桌今天坐滿了。", "（她把手帳闔起來）……今天的事做完了。剩下的不算。", "下一堂在 201。走吧。"], "when": [{"time": [7, 9], "location": ["campus", "library_hall"], "t": "（她嘴裡念著動詞變化）……行きます、行きました……啊。早。"}, {"week": [3, 6], "location": ["campus"], "t": "杜鵑花開了。……我已經拍了。"}, {"weekday": [4], "time": [19, 21], "location": ["wancai"], "week": [12, 18], "t": "讀書會快開始了。十分鐘，你要講什麼？"}, {"location": ["library_hall", "library"], "weather": "rain", "t": "下雨了。……我的傘借室友了。理由：她比較常忘記。"}, {"week": [16, 18], "t": "期末了。手帳右欄這週寫的是：再撐一下。"}]}}, "heroine_03": {"steps": [{"id": "Y2-L1", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "week": [1, 18], "lines": ["過年店裡休三天。……三天，阿姨不知道要做什麼。", "她把每一張椅子都擦了一遍。休假也在擦。"], "choices": [{"t": "「那妳呢？」", "reply": "我陪她擦。……我們家都這樣。"}, {"t": "「阿姨好認真。」", "reply": "……嗯。她說手停下來，會想東想西。"}], "rel": {"fam": 2}, "mem": "YT2_NEWYEAR"}, {"id": "Y2-L2", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "location": ["campus", "library_hall", "library"], "lines": ["這學期有一門課，要去訪問一個人。", "我想訪問阿姨。……她說不要。她說她又沒有什麼故事。"], "choices": [{"t": "「她有很多故事。」", "reply": "……嗯。我知道。她不知道。"}, {"t": "「換一個人訪問？」", "reply": "……不換。我等她答應。"}], "rel": {"fam": 2, "trust": 1}, "mem": "YT2_INTERVIEW"}, {"id": "Y2-L3", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "week": [6, 18], "lines": ["春假那幾天，店裡照開。我沒有出去。", "可是我在店門口，看到好多人拖著行李。……好像大家都要去別的地方。"], "choices": [{"t": "「下次一起出去？」", "reply": "……嗯。等店裡不忙。……店裡一直都很忙。等阿姨說可以。"}, {"t": "「店裡也很好。」", "reply": "……嗯。店裡不用拖行李。"}], "rel": {"fam": 2}, "note": "春假 4/3～4/6（交接包 v2 第 6～7 週）；說法用「那幾天」，第 6 週以後都說得通"}, {"id": "Y2-L4", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "week": [10, 18], "lines": ["阿姨換了一盞新的燈。舊的那盞，亮了二十年。", "……我把舊的拿回家了。捨不得丟。"], "choices": [{"t": "「留著很好。」", "reply": "……嗯。它看過很多碗麵。"}, {"t": "「舊燈會想念客人吧。」", "reply": "……嗯。你講話越來越像我。", "rel": {"comf": 1}}], "rel": {"fam": 2, "comf": 1}, "mem": "YT2_OLD_LAMP", "linesIf": [{"if": {"events": ["ev_yutong_absent"]}, "lines": ["阿姨的手好了。可以拿湯勺了。……她第一天就偷拿。", "她還換了一盞新的燈。舊的那盞亮了二十年，我拿回家了。"]}], "note": "**不說大一期中那週她顧店到很晚、在櫃台念書**——那是大二事件 10「期中考那一週」要讓玩家事後才知道的（AA_11）。看過語彤 4（ev_yutong_absent，阿姨包著護腕）的玩家只多聽到「阿姨的手好了」"}, {"id": "Y2-L5", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "week": [11, 18], "lines": ["最近阿姨話比較少。", "我就把桌子擦得比較乾淨。……好像這樣比較好。"], "choices": [{"t": "「會沒事的。」", "reply": "……嗯。你說的話，我先收著。"}, {"t": "「需要幫忙就說。」", "reply": "……嗯。會說。……可能不會。可是謝謝。", "rel": {"trust": 2}}], "rel": {"fam": 2, "trust": 1}, "mem": "YT2_WORRY", "linesIf": [{"if": {"events": ["ev_yutong_landlord"]}, "lines": ["房東的事，阿姨不讓我問。", "我就每天把桌子擦乾淨。好像這樣，店就不會被賣掉。"]}], "note": "語彤 6 房東來過了（ev_yutong_landlord，第 10 週以後）。沒看到那一晚的玩家，她不提房東（大二上事件 8 要能在沒有 RENT_RUMOR 時照常演）"}, {"id": "Y2-L6", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "week": [12, 18], "lines": ["阿哲最近每次都坐同一個位子。靠門口那邊。", "小語也是。……我只是說說。"], "choices": [{"t": "「妳看得好仔細。」", "reply": "……嗯。端麵的時候，會看到。"}, {"t": "「他們怎麼了？」", "reply": "……不知道。我只看到位子。"}], "rel": {"fam": 2}, "mem": "YT2_SEATS", "note": "小語 語 2「剛好路過」（第 16 週）之前的小徵兆，語彤只說看到的、不下結論；不能說成在一起（大二上才在一起）"}, {"id": "Y2-L7", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "lines": ["社會系大二開始，可以選的課比較多。我還沒想好要往哪裡走。", "阿姨說，選我喜歡的。我說我喜歡的不能賺錢。", "她說，那就選能讓你常回來吃麵的。"], "choices": [{"t": "「阿姨很懂。」", "reply": "……嗯。她什麼都懂。只是不說。"}, {"t": "「妳喜歡什麼？」", "reply": "……看人。聽人說話。……這個能當工作嗎？", "rel": {"trust": 2}}], "rel": {"fam": 2, "trust": 2}, "mem": "YT2_FUTURE"}, {"id": "Y2-L8", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "week": [15, 18], "lines": ["暑假學生走了，可是附近上班的人會來。店裡一樣忙。", "……你暑假在臺北嗎？週二、週四，還是一樣。"], "choices": [{"t": "「我會來。」", "reply": "……嗯。我會留滷蛋。", "rel": {"comf": 2}}, {"t": "「妳也要休息。」", "reply": "……嗯。阿姨也這樣說。我會休一天，陪我媽去走走。"}], "rel": {"fam": 2, "comf": 1}, "mem": "YT2_SUMMER", "note": "locTime 同大一上：在麵店只有週二、四 20:00～20:30 推進", "location": ["noodle", "campus", "library_hall", "library", "wenzhou"], "locTime": {"noodle": {"weekday": [2, 4], "time": [20, 20.5]}}}], "greet": {"base": ["……嗯。早。", "（她手上拿著一本社會學的書）……下午要交報告。", "……今天的湯是排骨。阿姨說的。", "……總圖今天冷氣好強。", "……你也來了。"], "when": [{"location": ["noodle"], "weekday": [2, 4], "time": [17.5, 20], "t": "……今天客人多。你先坐。"}, {"location": ["noodle"], "weekday": [2, 4], "time": [20, 20.5], "t": "……快打烊了。剩下的湯，阿姨說給你。"}, {"location": ["library_hall", "library"], "weekday": [1, 3, 5], "time": [19, 21.5], "t": "（她在靠窗的位子，小聲）……嗯。"}, {"weather": "rain", "t": "……下雨了。你有傘嗎？……我有兩把。"}, {"week": [16, 18], "location": ["noodle"], "t": "……期末了。長桌最近都是考生。"}]}}, "heroine_02": {"steps": [{"id": "Z2-L1", "if": {"stage": {"npc": "heroine_02", "min": "ACQUAINTANCE"}}, "unlessWorking": true, "lines": ["寒假我回台中，在家裡的店顧了三個禮拜。", "有一個高中生，同一份講義印了五次。每次都說「最後一次」。"], "choices": [{"t": "「後來呢？」", "reply": "第六次她沒來。我有點想她。……想那份講義。"}, {"t": "「妳都幫她印？」", "reply": "一張一塊。她那份一百頁。……我媽說她是好客人。"}], "rel": {"fam": 2}, "mem": "ZR2_WINTER_SHOP", "note": "接大一上 Z-L6（家裡開影印店）；沒聽過 Z-L6 的玩家也說得通（她自己說「家裡的店」）"}, {"id": "Z2-L2", "if": {"stage": {"npc": "heroine_02", "min": "ACQUAINTANCE"}}, "unlessWorking": true, "lines": ["這學期我修了一門翻譯。老師說，好的翻譯是讓人忘記它是翻譯。", "……我覺得很殘忍。做得越好，越沒有人記得你。"], "choices": [{"t": "「咖啡也是這樣？」", "reply": "……你很會接。對。好喝的時候，沒有人會想到是誰煮的。"}, {"t": "「那為什麼要做？」", "reply": "因為我自己知道。……這樣就夠了。大部分的時候。", "rel": {"trust": 1}}], "rel": {"fam": 2}, "note": "她對每個客人都很好、自己不被記得（Z5「我在台北，對每個客人都很好」）的前情；不說破"}, {"id": "Z2-L3", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "lines": ["三月的溫州街，常常下午就開始下雨。", "客人進來躲雨，點一杯最便宜的，坐一個小時。"], "choices": [{"t": "「老闆不會介意嗎？」", "reply": "老闆說，下雨天的客人最誠實。他們是真的需要這家店。"}, {"t": "「妳喜歡這種客人？」", "reply": "……喜歡。他們不趕時間。我也不用。", "rel": {"comf": 1}}], "rel": {"fam": 2, "comf": 1}, "linesIf": [{"week": [9, 18], "lines": ["溫州街下雨的時候，客人會進來躲雨。", "點一杯最便宜的，坐一個小時。這學期我借出去四把傘了。"]}], "note": "第 9 週以後推進的玩家不說「三月」（linesIf）"}, {"id": "Z2-L4", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "lines": ["你知道電影院最好的位子在哪裡嗎？", "不是正中間。是最後一排靠走道。看得到所有人在看同一個畫面。"], "choices": [{"t": "「為什麼想看別人？」", "reply": "大家在同一個地方笑的時候，我會覺得，沒有那麼一個人。", "rel": {"trust": 2}}, {"t": "「那樣看得清楚嗎？」", "reply": "看不太清楚。……所以同一部要看兩次。一次看電影，一次看人。"}], "rel": {"fam": 2}, "mem": "ZR2_BACK_ROW", "note": "Z5（第 12～13 週《東京物語》早場）和方奕廷 Z6（「她高中每天放學都去看二輪電影。一個人。」）的前情；這裡不提她一個人去"}, {"id": "Z2-L5", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "week": [9, 18], "lines": ["外文系的期中是寫報告。我寫一部電影裡的一句台詞，寫了八頁。", "老師的評語是：「很好，但妳躲在台詞後面。」"], "choices": [{"t": "「什麼意思？」", "reply": "……意思是，我都在寫別人說的話。沒寫我自己的。", "rel": {"trust": 2}}, {"t": "「八頁很厲害。」", "reply": "我也覺得。……可是她說得對。"}], "rel": {"fam": 2}, "mem": "ZR2_HIDE_BEHIND"}, {"id": "Z2-L6", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "week": [10, 18], "lines": ["這副眼鏡是高中配的。度數早就不對了。", "可是換了，看出去的東西會不一樣。……我還沒準備好。"], "extraIf": [{"if": {"memory": [{"npc": "heroine_02", "tag": "SHARED_SECRET"}]}, "lines": ["……交換的事也是。換了，看出去就不一樣了。"]}], "choices": [{"t": "「看不清楚不會累嗎？」", "reply": "會。所以我上課坐第一排。……騙你的，我坐最後一排。"}, {"t": "「換了也還是妳在看。」", "reply": "……這句可以放進電影裡。很肉麻的那種。", "rel": {"comf": 1}}], "rel": {"fam": 2, "trust": 1}, "mem": "ZR2_GLASSES", "note": "extraIf：Z4（第 12 週，SHARED_SECRET）聽過交換申請的玩家，她多一句；沒聽過的玩家不知道交換的事"}, {"id": "Z2-L7", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "week": [6, 18], "lines": ["打烊以後，我會自己在店裡坐十分鐘。不開燈。", "老闆說很浪費。可是十分鐘的電費，我算過，一塊多。"], "choices": [{"t": "「十分鐘在想什麼？」", "reply": "什麼都不想。……這是一整天唯一不用想的十分鐘。"}, {"t": "「那我不打擾妳的十分鐘。」", "reply": "嗯。……今天可以分你一分鐘。", "rel": {"comf": 2}}], "rel": {"fam": 2, "trust": 2}, "mem": "ZR2_TEN_MINUTES", "note": "只講打烊後的十分鐘；**不提她喝什麼**（Z3）"}, {"id": "Z2-L8", "if": {"stage": {"npc": "heroine_02", "min": "FAMILIAR"}}, "unlessWorking": true, "week": [15, 18], "lines": ["暑假我要回台中顧店。七月、八月。", "我媽說，店裡的冷氣比臺北的好。這是她的邀請方式。"], "linesIf": [{"if": {"memory": [{"npc": "heroine_02", "tag": "SHARED_SECRET"}]}, "lines": ["暑假我要回台中顧店。……交換的結果，暑假才會出來。", "我還沒跟我媽說。十點的電話，每天都差一點就說了。"]}], "choices": [{"t": "「回來的時候跟我說。」", "reply": "……好。我第二個傳給你。第一個是我媽。"}, {"t": "「好好休息。」", "reply": "顧店不算休息。……可是在家裡睡覺，比較不會作夢。"}], "rel": {"fam": 2, "comf": 1}, "mem": "ZR2_SUMMER", "note": "linesIf：聽過 Z4 的玩家；**交換的結果不在這裡說**（大二 BB_97 的事）"}], "greet": {"base": ["嗨。……這學期你比較常來。不是在算。", "（她把一本平裝小說蓋起來）休息時間剛好結束。", "今天店裡放老電影的配樂。聽不出來也沒關係。", "春天的溫州街，貓比人多。", "（她在吧檯後面舉了一下手）"], "when": [{"working": true, "t": "（她在吧檯後面點了一下頭，手沒停）"}, {"location": ["cafe"], "time": [21.5, 24], "t": "要打烊了。……你可以坐到我擦完這張桌子。"}, {"location": ["wenzhou"], "weekday": [6], "time": [14, 18], "t": "週六我不是店員。……所以不要叫我推薦。"}, {"weather": "rain", "t": "下雨了。……你沒帶傘吧。店裡還剩一把。"}, {"week": [16, 18], "t": "期末了。店裡的插座，每一個都有人。"}]}}, "heroine_04": {"steps": [{"id": "Q2-L1", "if": {"stage": {"npc": "heroine_04", "min": "ACQUAINTANCE"}}, "time": [14, 24], "lines": ["欸不是，寒假我在家寫了一個月的程式。", "我爸以為我在念書。他進來兩次，我都切到課本。……他很欣慰。"], "choices": [{"t": "「妳不怕被發現？」", "reply": "我寫了一個快捷鍵，按一下就切過去。這是我寒假最好的作品。"}, {"t": "「妳爸很關心妳。」", "reply": "關心和看得懂是兩件事。……好，下一題。", "rel": {"trust": 1}}], "rel": {"fam": 2}, "mem": "ZQ2_HOTKEY", "note": "家裡的壓力（大二以後「爸爸玩她的遊戲」那一場的前情）；不說爸爸要她做什麼"}, {"id": "Q2-L2", "if": {"stage": {"npc": "heroine_04", "min": "ACQUAINTANCE"}}, "time": [14, 24], "lines": ["吉他社這學期來了三個新生。三個都想先學最難的那首。", "我說先學會按和弦不會痛。他們看我的眼神，像我在講道理。"], "choices": [{"t": "「妳以前也是這樣？」", "reply": "我以前也想先學最難的那首。學了兩個月。然後乖乖去按和弦。"}, {"t": "「妳變成學姊了。」", "reply": "對。好可怕。這不是比喻。"}], "rel": {"fam": 2}}, {"id": "Q2-L3", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "week": [3, 18], "lines": ["系上又在問誰要去那個比賽。", "……我說我在考慮。意思是，我在考慮怎麼不去。"], "linesIf": [{"if": {"memory": [{"npc": "heroine_04", "tag": "CONTEST_DAY"}]}, "lines": ["比賽的結果出來了。我們系拿了第二名。", "……我傳了恭喜。真心的。只有一點點不真心。"]}, {"week": [10, 18], "lines": ["比賽的結果出來了。我們系拿了第二名。", "我沒去。……恭喜我傳了。真心的。大部分是。"]}], "choices": [{"t": "「妳還好嗎？」", "reply": "還好。……你問得太快，我還沒決定要不要不好。"}, {"t": "「那妳想做什麼？」", "reply": "做我的貓。這不是逃避。……好，有一點是。", "rel": {"trust": 1}}], "rel": {"fam": 2}, "note": "比賽在第 8～9 週（Q4）；第 10 週以後推進的玩家改說結果（linesIf）。和她在公館喝咖啡那天（CONTEST_DAY）的玩家用第一套"}, {"id": "Q2-L4", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "week": [5, 18], "lines": ["我的貓，這學期多了一個功能：牠會打呵欠。", "花了三個晚上。沒有人會注意到。可是牠現在比較像貓了。"], "linesIf": [{"if": {"memory": [{"npc": "heroine_04", "tag": "PLAYTESTED"}]}, "lines": ["你玩過的那個版本，貓現在會打呵欠了。", "花了三個晚上。……下次你看牠在第三個插座前面。"]}, {"unless": {"memory": [{"npc": "heroine_04", "tag": "ZQ_GAME_HEARD"}]}, "lines": ["我在做一個遊戲，主角是一隻貓。這學期牠會打呵欠了。", "花了三個晚上。沒有人會注意到。可是牠現在比較像貓了。"]}], "choices": [{"t": "「我會注意到。」", "reply": "你要先玩到。……好，總有一天。"}, {"t": "「三個晚上做打呵欠？」", "reply": "對。重要的事都很小。……這是我爸說的。他說的是別的事。"}], "rel": {"fam": 2, "comf": 1}, "note": "Q6（第 11 週，PLAYTESTED）測試過的玩家、大一上 Q-L5 沒聽過貓的玩家，各一套 linesIf"}, {"id": "Q2-L5", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "week": [10, 18], "lines": ["成發的歌單定了。我負責兩首。", "第二首有一個和弦我一直按不好。練了一千次。這是誇飾，八百次。"], "linesIf": [{"week": [15, 18], "lines": ["成發結束了。第二首我按錯一個和弦，全場安靜一秒。", "……然後我自己先笑出來。這是我今年最好的 bug。"]}], "extraIf": [{"week": [15, 18], "if": {"memory": [{"npc": "heroine_04", "tag": "CLAPPED"}]}, "lines": ["你有拍手。我看到了。……不要再提。"]}], "choices": [{"t": "「我想聽妳彈。」", "reply": "那下次社課來。我彈給你聽。只彈一次。"}, {"t": "「妳很勇敢。」", "reply": "欸不是。我只是很會假裝。……可能是同一件事。", "rel": {"trust": 1}}], "rel": {"fam": 2}, "note": "成發第 14 週（Q5）；第 15 週以後推進改說「結束了」（linesIf，按錯和弦是全場都看到的事）"}, {"id": "Q2-L6", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "week": [12, 18], "lines": ["阿凱最近打字比較快。我問他怎麼了，他說「沒事」。", "……他說「沒事」的時候，通常有事。你跟他同一間，你知道嗎？"], "choices": [{"t": "「他在想事情。」", "reply": "工程師想事情都很大聲。……好，我自己去問。"}, {"t": "「讓他自己說吧。」", "reply": "……嗯。你很像他的室友。我是說，很像好室友。", "rel": {"comf": 1}}], "rel": {"fam": 2}, "note": "阿凱 K2（Q6 之後，KAI_WANTS_CREDIT／TOLD_KAI_TELL_HER）的旁邊；她不知道阿凱說了什麼，玩家也不能替他說"}, {"id": "Q2-L7", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "lines": ["你知道我為什麼都穿這件外套嗎？", "口袋很大。一罐咖啡、一個隨身碟、一包衛生紙。這是我的全部家當。"], "choices": [{"t": "「還有吉他撥片吧。」", "reply": "……右邊口袋。你怎麼知道。你在觀察我？這不是問句。", "rel": {"comf": 1}}, {"t": "「那手機呢？」", "reply": "手機在左邊。它不算家當，它是麻煩。"}], "rel": {"fam": 2, "comf": 2}, "mem": "ZQ2_POCKETS"}, {"id": "Q2-L8", "if": {"stage": {"npc": "heroine_04", "min": "FAMILIAR"}}, "time": [14, 24], "week": [15, 18], "lines": ["暑假我跟我爸說我要去實習。他很開心。", "實習的公司叫「貓」。老闆是我。……我沒有說謊。"], "choices": [{"t": "「需要測試員嗎？」", "reply": "需要。不支薪。包飲料。這不是問句。", "mem": "ZQ2_SUMMER_TESTER"}, {"t": "「妳爸會發現吧。」", "reply": "會。九月的時候。到時候再說。……下一題。"}], "rel": {"fam": 2, "comf": 1}}], "greet": {"base": ["欸。", "我剛起床。現在下午三點。這很正常。", "（她把耳機拿下來一邊）……說。", "今天寫了兩百行，刪了一百九十行。進度很好。", "滷味今天沒開。世界末日。"], "when": [{"location": ["wancai"], "weekday": [1, 3], "time": [19, 21], "t": "社課。要進來聽嗎？不聽也可以站在門口。"}, {"week": [8, 9], "t": "……期中。我睡系館。不要告訴阿凱，他會告訴全世界。"}, {"weather": "rain", "t": "下雨。我的吉他袋防水。我不防水。"}, {"time": [14, 16], "t": "我早餐吃完了。現在是下午兩點。……對，早餐。"}, {"week": [16, 18], "t": "期末。我現在靠咖啡和怨念活著。"}]}}, "heroine_05": {"friendOnly": true, "steps": [{"id": "S2-L1", "if": {"stage": {"npc": "heroine_05", "min": "ACQUAINTANCE"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "lines": ["學弟。兩件事。", "一，總圖二樓的飲水機修好了。二，三樓的壞了。……這棟樓的飲水機在輪流。"], "choices": [{"t": "「學姊都在注意飲水機。」", "reply": "我一天裝三次保溫瓶。我比總務處清楚。"}, {"t": "「謝謝學姊。」", "reply": "不用謝。這是公共服務。"}], "rel": {"fam": 2}, "note": "大一上 S-L1（二樓壞了，去三樓裝）的回聲；沒聽過的玩家也說得通"}, {"id": "S2-L2", "if": {"stage": {"npc": "heroine_05", "min": "ACQUAINTANCE"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "lines": ["這學期我修行政救濟。大家說很難。", "難的不是條文。是你要先想像一個人，被擋在門外很久。"], "choices": [{"t": "「學姊想像得到？」", "reply": "想像得到。所以我念得很慢。……這不是缺點。"}, {"t": "「我們大一還沒教。」", "reply": "我知道。所以我先說。你以後上到，會覺得我說過。", "rel": {"resp": 1}}], "rel": {"fam": 2, "resp": 1}, "note": "大一上 S-L7（被政府擋住的事）的延伸；不講法律結論"}, {"id": "S2-L3", "if": {"stage": {"npc": "heroine_05", "min": "ACQUAINTANCE"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "week": [5, 18], "lines": ["家族一學期聚一次。下一次 Kevin 選地方。", "……我已經先查了評價。這不是不信任他。是了解他。"], "linesIf": [{"if": {"memory": [{"npc": "heroine_05", "tag": "FAMILY_DINNER"}]}, "lines": ["上次的咖哩，我點了辣的。我不後悔。", "……下一次 Kevin 選地方。我已經先查了評價。這不是不信任他。"]}], "choices": [{"t": "「Kevin 學長選的會很奇怪嗎？」", "reply": "上次他選了一家只有站位的。重點是，我們站了兩個小時。"}, {"t": "「學姊很照顧家族。」", "reply": "……照顧是你們的說法。我只是不想大家吃壞肚子。"}], "rel": {"fam": 2}, "note": "W2b／W2c（第 3～4 週，家族群組「Kevin 遲到七分鐘，下次地方他選」大家都看得到）之後；去過聚餐的玩家用 linesIf"}, {"id": "S2-L4", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "lines": ["我的研究計畫，改到第七版了。", "許老師說第六版比較好。……所以第七版是把第六版改回來。"], "choices": [{"t": "「那第七版有什麼不一樣？」", "reply": "不一樣的是我。我現在知道第六版為什麼好了。", "rel": {"resp": 1}}, {"t": "「學姊要睡覺。」", "reply": "一，我有睡。二，……好，第七版改完就睡。"}], "rel": {"fam": 2}, "mem": "SIS2_PLAN_V7", "note": "W3「我自己的研究計畫還沒改完」的同一份"}, {"id": "S2-L5", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "week": [10, 18], "lines": ["期中的時候，我對著空的保溫瓶喝了好幾次。", "……沒有人看到。我自己發現的。我覺得很好笑。"], "linesIf": [{"if": {"memory": [{"npc": "heroine_05", "tag": "HELPED"}]}, "lines": ["保溫瓶上那張「已裝滿」，我貼了一個禮拜。", "有人問我是誰寫的。我說是保溫瓶自己寫的。"]}, {"if": {"memory": [{"npc": "heroine_05", "tag": "NOTICED_HER"}]}, "lines": ["上次的保溫瓶，你看到了。", "……我後來設了鬧鐘。每兩個小時看一下瓶子。不是開玩笑。"]}], "choices": [{"t": "「學姊太累了。」", "reply": "一，期中大家都累。二，……好，我承認。三，下一題。"}, {"t": "「下次一起注意。」", "reply": "好。看到了就說。重點是，說小聲一點。"}], "rel": {"fam": 2, "comf": 1}, "note": "W4（第 8～9 週）的回聲：買咖啡的玩家（HELPED）、看到的玩家（NOTICED_HER）各一套；沒遇到的玩家，她自己說"}, {"id": "S2-L6", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "week": [10, 18], "lines": ["我大一的時候，也被學姊改過書狀。改了十二條。", "我在廁所哭完，回去寫第二版。……這件事法服的人都知道。我自己講的。"], "choices": [{"t": "「第二版有比較好嗎？」", "reply": "好很多。第三版又更好。重點是，有第二版。"}, {"t": "「現在換學姊改別人。」", "reply": "對。所以我改的時候，會多想一下。"}], "rel": {"fam": 2, "trust": 2}, "mem": "SIS2_FIRST_DRAFT", "note": "W5（第 17～18 週，便條）的前情：這裡不提便條，只說她自己被改過；講出來就不丟臉，是她的個性（不是只對玩家說的祕密）"}, {"id": "S2-L7", "if": {"stage": {"npc": "heroine_05", "min": "FAMILIAR"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "lines": ["我媽問我，研究所念完，是不是就去考司法官。", "我說對。……說「對」的速度，比我想的慢一點。"], "choices": [{"t": "「學姊自己想嗎？」", "reply": "一，想。二，……我在找二。找到了再說。"}, {"t": "「慢一點也沒關係。」", "reply": "……你說得很像我會說的話。不要學我。", "rel": {"trust": 1}}], "rel": {"fam": 2, "trust": 1}, "mem": "SIS2_SLOWER_YES", "note": "大一上 S-L5（爸媽說考上司法官很好）的下一步；不決定她的方向"}, {"id": "S2-L8", "if": {"stage": {"npc": "heroine_05", "min": "FRIEND"}}, "unlessWeekdayTime": {"weekday": [5], "time": [17, 21]}, "week": [15, 18], "lines": ["三件事。一，期末不要熬夜。二，熬夜的話，不要喝三倍濃的。", "三，暑假讀書會停。你要自己讀。開學我會問。"], "choices": [{"t": "「學姊暑假做什麼？」", "reply": "寫研究計畫。第八版。……還有睡覺。這是一件事，不是兩件。"}, {"t": "「學姊也不要熬夜。」", "reply": "……一，知道了。二，你管很多。三，謝謝。"}], "rel": {"fam": 2}, "note": "沒加法服的玩家也說得通（「你要自己讀」）"}], "greet": {"base": ["學弟。", "一件事：保溫瓶我裝了。不用問。", "（她從判決上抬頭，點一下）", "總圖三樓今天有位子。只是告訴你。", "兩件事。一，吃飯。二，沒有二。"], "when": [{"location": ["library", "library_hall"], "week": [8, 9], "t": "……期中。不要跟我講話。一句可以。"}, {"weekday": [3], "time": [17, 19.5], "t": "今天週三。七點，萬才館。"}, {"weekday": [6], "time": [8, 12.5], "t": "今天法服值班。不是叫你來，是告訴你我在哪。", "note": "單週週六上午（法服方案 A）；雙週不說"}, {"weather": "rain", "t": "下雨。兩件事。一，帶傘。二，不要跑。"}, {"week": [16, 18], "t": "期末。重點是，睡覺。"}]}}, "classmate_peishan": {"friendOnly": true, "steps": [{"id": "P2-L1", "if": {"stage": {"npc": "classmate_peishan", "min": "ACQUAINTANCE"}}, "lines": ["寒假我在家裡的早餐店幫了一個月。", "我現在可以一次端六盤。……這個技能在法律系沒有用。"], "choices": [{"t": "「說不定有用。」", "reply": "哪裡？……好，期末考的時候我一次拿六支筆。"}, {"t": "「六盤很厲害。」", "reply": "我爸說七盤才算出師。我還差一盤。"}], "rel": {"fam": 2}, "mem": "PS2_SIX_PLATES", "note": "接大一上 P-L2（家裡開早餐店）；沒聽過的玩家也說得通"}, {"id": "P2-L2", "if": {"stage": {"npc": "classmate_peishan", "min": "ACQUAINTANCE"}}, "lines": ["這學期我還是去旁聽哲學系。這次是倫理學。", "老師說，「應該」是世界上最難的兩個字。"], "choices": [{"t": "「法律也一直在說應該。」", "reply": "對吧！所以兩邊在吵同一件事。……我又想太多了嗎。"}, {"t": "「妳比較喜歡哲學？」", "reply": "……我不知道。我喜歡的是問問題。法律比較常給答案。", "rel": {"trust": 1}}], "rel": {"fam": 2}, "note": "大二 P3「我要重考，去念教育」的遠伏筆；不說出口"}, {"id": "P2-L3", "if": {"stage": {"npc": "classmate_peishan", "min": "ACQUAINTANCE"}}, "week": [5, 18], "lines": ["我在溫州街的課輔班當志工。一週三天。", "小孩問問題的時候，我都先想：他真正想問的是什麼。"], "linesIf": [{"if": {"memory": [{"npc": "classmate_peishan", "tag": "SAW_HER_TEACH"}]}, "lines": ["上次你在溫州街看到的那班，有一個小孩問我你是誰。", "我說是同學。他說「喔」。……小孩的「喔」好有殺傷力。"]}], "choices": [{"t": "「這跟讀法律很像。」", "reply": "……你這樣說，我好像比較喜歡法律了。一點點。"}, {"t": "「妳很適合教小孩。」", "reply": "真的嗎？……我會記住這句。不是客套的那種記住。", "rel": {"trust": 1}}], "rel": {"fam": 2}, "mem": "PS2_TUTOR_HEARD", "note": "P3b（第 5 週起，SAW_HER_TEACH）遇過的玩家用 linesIf；沒遇過的玩家她自己說"}, {"id": "P2-L4", "if": {"stage": {"npc": "classmate_peishan", "min": "ACQUAINTANCE"}}, "week": [9, 18], "lines": ["期中以後，大家都知道我跟柏翰在一起了。我自己說的。", "我不喜歡讓大家猜。猜比問還累。"], "choices": [{"t": "「恭喜。」", "reply": "謝謝。……被說恭喜好奇怪，好像我考上了什麼。"}, {"t": "「妳說得很直接。」", "reply": "早餐店長大的。客人點什麼，就直接喊出來。"}], "rel": {"fam": 1}, "note": "BB_100 2-3：交往是公開、直接讓大家知道的；麵店那句「對，我們在一起了。你們吃你們的。」只在麵店事件說，這裡不重複。只有朋友的話"}, {"id": "P2-L5", "if": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}}, "week": [9, 18], "lines": ["期中的刑總，最後一題我寫了一個不確定的答案。", "手在抖。可是我決定不擦掉。"], "choices": [{"t": "「結果呢？」", "reply": "對了一半。……可是是我自己的一半。"}, {"t": "「不擦掉很勇敢。」", "reply": "是嗎。我以為只是來不及擦。……好，就當勇敢。"}], "rel": {"fam": 2, "trust": 1}, "mem": "PS2_NOT_ERASED"}, {"id": "P2-L6", "if": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}}, "week": [6, 18], "lines": ["這學期我回桃園的次數變少了。", "我媽在電話裡說：「少一個人，蛋都煎得比較好。」……她是在說想我。"], "choices": [{"t": "「妳媽很會說話。」", "reply": "她只會這種說法。我們家是說反話的家族。"}, {"t": "「回去看看她吧。」", "reply": "……嗯。這週末。我端七盤給她看。", "rel": {"comf": 1}}], "rel": {"fam": 2, "comf": 1}}, {"id": "P2-L7", "if": {"stage": {"npc": "classmate_peishan", "min": "FAMILIAR"}}, "lines": ["我常常在想，我是因為喜歡才念法律，還是因為考上了。", "……你不用回答。我只是想說出來，聽聽看它是什麼聲音。"], "choices": [{"t": "「聽起來像一個好問題。」", "reply": "……好問題通常沒有答案。我先放著。"}, {"t": "「我也想過。」", "reply": "真的嗎？……那我不是唯一一個。這樣就好。", "rel": {"trust": 1}}], "rel": {"fam": 2, "trust": 2}, "mem": "PS2_WHY_LAW", "note": "大二 P3 的伏筆（課輔班是她「不會看時間」的地方）；不寫成憂鬱或逃避（BB_96 3-3）"}, {"id": "P2-L8", "if": {"stage": {"npc": "classmate_peishan", "min": "FRIEND"}}, "week": [15, 18], "lines": ["暑假我要在課輔班帶夏令營，兩個禮拜。還有回家煎蛋。", "……我的暑假好像都在照顧別人。我好像滿喜歡的。"], "choices": [{"t": "「這很像妳。」", "reply": "……謝謝。這句我留著。"}, {"t": "「也要照顧自己。」", "reply": "好。……我會把自己排進去。第三順位。"}], "rel": {"fam": 2, "comf": 1}}], "greet": {"base": ["嗨！", "我剛從課輔班回來，手上都是紅筆。", "你吃早餐了嗎？……這是職業病。", "（她揮了揮一疊作業本）", "我要去旁聽倫理學。下次聊！"], "when": [{"location": ["wenzhou"], "weekday": [2, 4], "time": [16.5, 18], "t": "（她帶著一排小孩過馬路，對你點頭）……等一下！"}, {"week": [8, 9], "t": "期中。我背到交流道了。……我是說，背到第三章。"}, {"weather": "rain", "t": "下雨了。今天小孩一定很吵。"}, {"time": [6, 8], "t": "早。我六點就醒了。身體還記得要煎蛋。"}, {"week": [16, 18], "t": "期末。筆記拼好了，要的話跟我說。"}]}}, "kexin": {"context": "date", "steps": [{"id": "K2-L1", "if": {"flags": ["dating_kexin"]}, "lines": ["寒假我們視訊了二十三次。我有記。", "……不要覺得可怕。記帳是我的興趣。"], "choices": [{"t": "「二十三次很多嗎？」", "reply": "假設一天一次，寒假有二十八天。……所以缺五次。這學期補。"}, {"t": "「我也有記。」", "reply": "騙人。……你記幾次？不准說。我會比。", "rel": {"comf": 1}}], "rel": {"comf": 2}, "mem": "KX2_23_CALLS"}, {"id": "K2-L2", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "week": [2, 18], "lines": ["政大的山，春天早上會起霧。", "早上的課，教室外面是白的。……像在雲裡面上民法。"], "choices": [{"t": "「很浪漫。」", "reply": "不浪漫。很濕。我的頭髮整天都在抗議。"}, {"t": "「我想看。」", "reply": "那你早上八點來。……假設你起得來。"}], "rel": {"comf": 2}, "linesIf": [{"week": [9, 18], "lines": ["政大的山，下雨的早上還是會起霧。", "教室外面是白的。……像在雲裡面上民法。"]}]}, {"id": "K2-L3", "if": {"flags": ["dating_kexin"]}, "dateOnly": "video", "lines": ["予樂這學期當讀書會組長了。第一次開會，她先發了一張議程。", "邵鈞問議程有沒有出處。……我笑到被踢出會議。"], "choices": [{"t": "「妳被踢出去了？」", "reply": "十秒。予樂又把我拉回來。她說沒有我，會開得太快。"}, {"t": "「邵鈞好認真。」", "reply": "他是認真的那種好笑。我們需要他。"}], "rel": {"comf": 1, "fam": 1}, "note": "大一上 K-L3（予樂、邵鈞）的同一組人"}, {"id": "K2-L4", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "week": [5, 18], "lines": ["這學期我少說了很多「假設」。予樂說我變了。", "我說沒有，是假設用完了。……其實是你在的時候，我不太需要假設。"], "choices": [{"t": "「那我一直在。」", "reply": "……不要講這種話。我會想錄起來。", "rel": {"comf": 2}}, {"t": "「妳想假設也可以。」", "reply": "好。假設今天不下雨。……你看，下雨了。假設失敗。"}], "rel": {"comf": 2, "trust": 1}, "mem": "KX2_FEWER_IFS", "note": "大一上 K-L8「今天不假設」的下一步；不是收起招牌句（大三下的事）"}, {"id": "K2-L5", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "week": [5, 18], "lines": ["從政大到你們學校的公車，我閉著眼睛都知道到哪了。", "過了橋，就是還有十二分鐘。……我都在那十二分鐘補口紅。不要看。"], "choices": [{"t": "「我沒看。」", "reply": "你有。你在看我的耳環。……好，耳環可以看。"}, {"t": "「下次我去政大找妳。」", "reply": "好。可是我們的公車比較晃。你會暈。我算過了，你會。"}], "rel": {"comf": 2}}, {"id": "K2-L6", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "week": [10, 18], "lines": ["政大的流蘇，四月底開。開的時候像下雪。", "我生日那幾天剛好。我覺得它在幫我慶祝。……我知道不是。"], "choices": [{"t": "「它就是在幫妳慶祝。」", "reply": "……好。那我接受。明年它也要來。"}, {"t": "「明年我們一起看。」", "reply": "……你又講這種話。好，我記下來了。我會提醒你。", "rel": {"comf": 1}}], "rel": {"comf": 2}, "mem": "KX2_TASSEL", "note": "生日（4/24，第 9 週，BCG-45 流蘇與蠟燭）之後；沒去生日那晚的玩家也說得通"}, {"id": "K2-L7", "if": {"flags": ["dating_kexin"]}, "dateOnly": "meet", "week": [10, 18], "lines": ["我們的日子，我每次都會排一張行程表。", "可是每次都沒照著走。……我開始覺得，行程表是用來被打亂的。"], "choices": [{"t": "「那就不要排了。」", "reply": "不行。沒排的話，我不知道哪裡被打亂了。"}, {"t": "「我喜歡被打亂的部分。」", "reply": "……我也是。可是不要說出來，我會不想排了。", "rel": {"comf": 1}}], "rel": {"comf": 2}, "mem": "KX2_PLAN_SHEET", "note": "她還是會排（大三下「這次不排行程表」才收起來，那是她自己的轉變，這裡不提前）"}, {"id": "K2-L8", "if": {"flags": ["dating_kexin"]}, "week": [15, 18], "lines": ["暑假我要回家兩個禮拜。", "……我算過了，兩個禮拜是我能忍的最多。不是撒嬌，是統計。"], "choices": [{"t": "「我去找妳。」", "reply": "……真的嗎？假設你真的來，我帶你去吃我家巷口的豆花。", "rel": {"comf": 2}}, {"t": "「兩個禮拜很快。」", "reply": "對你很快。對我是十四天。……我每天傳一張照片。"}], "rel": {"comf": 2}, "mem": "KX2_SUMMER"}], "greet": null}}, "Y2S1": {"heroine_01": {"steps": [{"id": "A3-L1", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "lines": ["這學期我開始家教。國中二年級，數學。", "學生問我為什麼要學證明。我說：因為要說服別人。學生說不想說服別人。"], "choices": [{"t": "「那妳怎麼回？」", "reply": "我說：那就說服自己。……學生翻白眼了。"}, {"t": "「國中生很難教吧。」", "reply": "不難。只是還沒找到理由。"}], "rel": {"fam": 2}, "mem": "AN3_TUTOR", "note": "新 10「家教學生的家」（第 13 週）的伏筆；**不提學生家裡的事**、不寫學生性別（新 13 的卡片「老師，謝謝妳畫的那張圖」）"}, {"id": "A3-L2", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "lines": ["日文課升到中級了。老師說我的敬語用太多。", "我說那是禮貌。老師說，那是距離。"], "choices": [{"t": "「哪一個對？」", "reply": "……都對。我在想要留多少距離。"}, {"t": "「敬語很難嗎？」", "reply": "不難。難的是什麼時候不用。"}], "rel": {"fam": 2}, "mem": "AN3_KEIGO", "note": "大三上新 15「為什麼是日本」的伏筆；這裡仍不說交換"}, {"id": "A3-L3", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [8, 18], "lines": ["公法讀書會的規則，我重寫了。從一頁變三條。", "小語說我進步了。我說那叫刪減。"], "choices": [{"t": "「三條是哪三條？」", "reply": "每人十分鐘。離題可以，要拉回來。第三條……來了就知道。"}, {"t": "「刪得好。」", "reply": "……謝謝。刪的時候很痛。"}], "rel": {"fam": 2}, "note": "新 8（第 7 週）之後；去過、沒去過讀書會都說得通（沒加入的玩家在群組看過小語撕規則）"}, {"id": "A3-L4", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "week": [9, 18], "lines": ["大二的課變多了。我早上跑步多跑一圈。", "理由：要想的事變多了。跑步的時候，比較想得清楚。"], "choices": [{"t": "「想清楚了嗎？」", "reply": "……一半。另一半跑完就忘了。"}, {"t": "「我也去跑？」", "reply": "早上六點。不准遲到。……你不會來的。", "rel": {"comf": 1}}], "rel": {"fam": 2, "comf": 1}, "linesIf": [{"unless": {"memory": [{"npc": "heroine_01", "tag": "AN_L7_RUN"}]}, "lines": ["大二的課變多了。我每天早上六點去跑步，最近多跑一圈。", "理由：要想的事變多了。跑步的時候，比較想得清楚。"]}], "note": "回聲大一上 A-L7（早上六點跑步）；沒聽過的玩家用 linesIf"}, {"id": "A3-L5", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "week": [13, 18], "lines": ["行政法那堂，我改了答案。第一次在課堂上改。", "不是因為輸了。是因為對方的理由比較好。"], "choices": [{"t": "「改答案不丟臉。」", "reply": "我知道。……我只是要多說一次給自己聽。"}, {"t": "「誰的理由？」", "reply": "……不告訴你。理由：會驕傲。"}], "rel": {"fam": 2, "trust": 1}, "note": "新 9（第 12 週行政法 C 類）之後；玩家是不是站她對面都說得通"}, {"id": "A3-L6", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "week": [15, 18], "lines": ["小語跟阿哲在一起了。", "讀書會現在要排座位。理由：他們坐在一起會一直講話。"], "choices": [{"t": "「妳早就知道？」", "reply": "……全世界都知道。只有他們以為沒人知道。"}, {"t": "「排座位好嚴格。」", "reply": "不嚴格。是保護其他人的十分鐘。"}], "rel": {"fam": 2}, "note": "小語 語 3「在一起」（第 15 週系籃賽後）"}, {"id": "A3-L7", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "lines": ["這學期好多人來借我的筆記。", "被需要的感覺很好。……可是我開始分不清楚，哪些是我自己想做的。"], "choices": [{"t": "「妳想做什麼？」", "reply": "……還在找。可能是讀書會，可能是家教。可能都不是。", "rel": {"trust": 2}}, {"t": "「可以拒絕啊。」", "reply": "……我在練習。理由欄寫：不行。兩個字，很難寫。"}], "rel": {"fam": 2, "trust": 2}, "mem": "AN3_NEEDED", "note": "和主線 4「被需要的一年」（祐廷）互相照：她也在問同一件事"}, {"id": "A3-L8", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "week": [16, 18], "lines": ["寒假回台中。我媽說，這次換我教她一道菜。", "……我只會一道。她說那就教那一道。"], "choices": [{"t": "「番茄炒蛋？」", "reply": "……你記得。……對。"}, {"t": "「教得會嗎？」", "reply": "她學得很快。她說，看我做過一次就夠了。"}], "rel": {"fam": 2, "comf": 2}, "mem": "AN3_WINTER", "linesIf": [{"if": {"memory": [{"npc": "heroine_01", "tag": "AN2_TOMATO_EGG"}]}, "lines": ["寒假回台中。我媽說，這次換我教她一道菜。", "……你知道的。我只會番茄炒蛋。她說那就教那個。"]}], "note": "接大一下 A2-L1（番茄炒蛋）；大二下新 12「媽媽的晚餐（二）」前的日常，不談案子、不提媽媽職業"}], "greet": {"base": ["早。今天有行政法。我很期待。……這句不是反話。", "我剛家教完。學生今天問我，法律系是不是都要背。", "（她的手帳換了一本新的）……舊的寫滿了。", "讀書會的白板，我擦乾淨了。下週輪到你擦。", "霖澤館的電梯又在修。走樓梯。"], "when": [{"weekday": [4], "time": [19, 21], "location": ["wancai"], "t": "讀書會快開始了。今天第一個十分鐘是你。……騙你的。"}, {"time": [7, 9], "location": ["campus", "library_hall"], "t": "（她剛下日文課）……おはようございます。……早。"}, {"week": [8, 9], "t": "期中。手帳右欄這週寫的是：撐住。"}, {"location": ["library_hall", "library"], "weather": "rain", "t": "下雨了。……這次我有帶傘。理由：去年借出去的都沒回來。"}, {"week": [16, 18], "t": "期末了。我把讀書會的時間改成兩週一次。理由：大家都要活下去。"}]}}, "heroine_03": {"steps": [{"id": "Y3-L1", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "lines": ["暑假我讀了三本書。都是客人留在店裡的。", "一本講海，一本講考試。一本沒有封面。"], "choices": [{"t": "「沒有封面的那本在講什麼？」", "reply": "……講一個人一直在等。我很喜歡。"}, {"t": "「客人會回來拿嗎？」", "reply": "……不會。阿姨說，留下來的書，就是店的。"}], "rel": {"fam": 2}, "mem": "YT3_BOOKS"}, {"id": "Y3-L2", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "week": [6, 18], "lines": ["我加入法服了。初談組。", "……我不會法律。我會聽。學姊說，這樣就夠了。"], "choices": [{"t": "「妳一定很適合。」", "reply": "……嗯。阿姨也這樣說。她說我從小就在聽客人抱怨。"}, {"t": "「法服累嗎？」", "reply": "隔週週六早上。比顧店輕鬆。"}], "rel": {"fam": 2}, "mem": "YT3_FAFU", "note": "語彤事件 7（第 5 週週六第一次值班，AA_140 G03）之後；**不講阿伯那一句**（事件 7 的戲）。法服＝隔週週六 9～12 民眾諮詢、週三晚上內部讀書會（AA_132）"}, {"id": "Y3-L3", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "lines": ["這學期有一門課在講家庭。老師問：你家的晚餐誰煮？", "全班只有我說：阿姨。"], "choices": [{"t": "「老師怎麼說？」", "reply": "老師說，這就是這門課要講的。……我變成例子了。"}, {"t": "「阿姨煮的最好吃。」", "reply": "……嗯。我也這樣寫在作業上。"}], "rel": {"fam": 2, "trust": 1}}, {"id": "Y3-L4", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "week": [8, 18], "lines": ["初談組有一本記錄本。我寫得最短。", "學姊說短的比較好讀。……我只是寫不出長的。"], "choices": [{"t": "「短的才好。」", "reply": "……嗯。長的我記在心裡。"}, {"t": "「可以給我看嗎？」", "reply": "……不行。那是別人的事。", "rel": {"trust": 1}}], "rel": {"fam": 2}}, {"id": "Y3-L5", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "week": [15, 18], "lines": ["……阿哲跟小語在一起了。", "我端麵的時候就看出來了。"], "choices": [{"t": "「妳好厲害。」", "reply": "……嗯。看人是我唯一會的。"}, {"t": "「要告訴他們妳早就知道嗎？」", "reply": "……不用。他們以為沒人知道。讓他們以為。"}], "rel": {"fam": 2}, "linesIf": [{"if": {"memory": [{"npc": "heroine_03", "tag": "YT2_SEATS"}]}, "lines": ["……阿哲跟小語在一起了。", "位子。我說過的。"]}], "note": "接大一下 Y2-L6（YT2_SEATS）"}, {"id": "Y3-L6", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "lines": ["我媽最近開始散步。傍晚，在汀州路走一圈。", "週末我陪她。她走得比我慢，可是講得比我多。"], "choices": [{"t": "「真好。」", "reply": "……嗯。很好。"}, {"t": "「下次我也一起？」", "reply": "……嗯。下次。她走很慢喔。", "rel": {"comf": 2}}], "rel": {"fam": 2, "trust": 2}, "mem": "YT3_MOM_WALK", "note": "媽媽身體不好的細節不寫（AA_11 第 0 節）；這裡只寫她慢慢變好的一件小事"}, {"id": "Y3-L7", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "lines": ["學姊說，初談組以後要有人顧。……她是看著我說的。", "我第一次被交代一件很久以後的事。"], "choices": [{"t": "「妳可以的。」", "reply": "……嗯。我會先學會倒水。"}, {"t": "「會有壓力嗎？」", "reply": "……有。可是是好的那種。像一次端兩碗麵。"}], "rel": {"fam": 2, "trust": 2}, "mem": "YT3_INTAKE_LEAD", "note": "學姊大二下第 15 週畢業時，語彤接初談組長（交接包 v3 第 4 節第 1 點）；這裡只是學姊的一句話，不是正式交接"}, {"id": "Y3-L8", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "week": [16, 18], "lines": ["過年店休三天。今年我想帶阿姨去看海。", "她說不要。說了兩次不要，才說好。"], "choices": [{"t": "「去哪裡的海？」", "reply": "……還沒想好。近的就好。阿姨說，海都一樣。"}, {"t": "「我可以推薦。」", "reply": "……嗯。你推薦，我再跟她說是我想的。", "rel": {"comf": 2}}], "rel": {"fam": 2, "comf": 1}, "mem": "YT3_SEA"}], "greet": {"base": ["……嗯。", "（她抱著初談的記錄本）……要拿去還學姊。", "……阿姨今天的湯放了白蘿蔔。很甜。", "……總圖靠窗那排，今天被占了。", "……你也來了。……嗯，好。"], "when": [{"weekday": [6], "time": [9, 12], "location": ["wancai"], "t": "（她坐在初談的桌子後面）……先坐。要喝水嗎？"}, {"location": ["noodle"], "weekday": [2, 4], "time": [17.5, 20], "t": "……今天客人多。你先坐那邊。"}, {"location": ["library_hall", "library"], "weekday": [1, 3, 5], "time": [19, 21.5], "t": "（她在靠窗的位子，小聲）……嗯。"}, {"week": [8, 9], "t": "……期中。總圖今天人好多。"}, {"weather": "rain", "t": "……下雨了。我帶了兩把傘。……習慣。"}]}}}, "Y2S2": {"heroine_01": {"steps": [{"id": "A4-L1", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [3, 18], "location": ["campus"], "lines": ["（她又對著同一叢杜鵑花舉起手機）……第二張。", "跟去年比，樹變大了。……還是我變了。"], "choices": [{"t": "「都有吧。」", "reply": "……嗯。理由：一年了。"}, {"t": "「給我看第一張。」", "reply": "……不行。四張拍完才給看。"}], "rel": {"fam": 2}, "mem": "AN4_AZALEA2", "linesIf": [{"week": [7, 18], "lines": ["杜鵑花謝了。三月的時候，我拍了第二張。", "跟去年比，樹變大了。……還是我變了。"]}], "extraIf": [{"unless": {"memory": [{"npc": "heroine_01", "tag": "AN2_AZALEA"}]}, "lines": ["……我每年在同一個位置拍一張。四年，四張。"]}], "note": "四年四張的第二張（交接包 v3 第 3 週）；沒聽過第一張的玩家多一句說明"}, {"id": "A4-L2", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "week": [5, 18], "lines": ["交換說明會，我坐第一排。理由：後面聽不清楚。", "我還沒決定。……只是先聽。"], "choices": [{"t": "「妳想去哪裡？」", "reply": "……理由還在寫。快寫完了。"}, {"t": "「我也在想。」", "reply": "那下次說明會，你坐我旁邊。第一排。", "rel": {"comf": 1}}], "rel": {"fam": 2}, "mem": "AN4_EXCHANGE_TALK", "note": "主線 8 交換說明會（第 4 週）之後；**不說日本**（大三上新 15 才說為什麼是日本）"}, {"id": "A4-L3", "if": {"stage": {"npc": "heroine_01", "min": "ACQUAINTANCE"}}, "lines": ["我室友說，她明年要選樓長。", "理由：她想把「記點以前先問」那一條，寫進規則。"], "choices": [{"t": "「妳會投她嗎？」", "reply": "會。……她的政見只有一條。我很喜歡。"}, {"t": "「妳教的？」", "reply": "不是。她自己想的。……我只是幫她把字改短。"}], "rel": {"fam": 2, "trust": 1}, "note": "回聲大一下新 5（舍友的記點申訴）；沒遇過那件事的玩家也聽得懂"}, {"id": "A4-L4", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "lines": ["學生這次段考，數學考了七十分。", "學生說，證明題終於有理由了。……這句我要記下來。"], "choices": [{"t": "「妳教得很好。」", "reply": "……是學生自己找到的。我只是一直問「為什麼」。"}, {"t": "「七十分很好嗎？」", "reply": "上次四十二。理由很充分。"}], "rel": {"fam": 2, "comf": 1}, "linesIf": [{"unless": {"memory": [{"npc": "heroine_01", "tag": "AN3_TUTOR"}]}, "lines": ["我家教的學生，這次段考數學考了七十分。", "學生說，證明題終於有理由了。……這句我要記下來。"]}], "note": "接大二上 A3-L1；**不提學生家裡的事**（新 10、13 的戲）"}, {"id": "A4-L5", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "lines": ["日文老師說，我的敬語變少了。", "……我在練習不要那麼有距離。不知道是好事還是壞事。"], "choices": [{"t": "「好事。」", "reply": "……你這麼快就回答。……好，我收下。"}, {"t": "「對誰練習？」", "reply": "……對老師。還有一些人。"}], "rel": {"fam": 2, "comf": 1}, "linesIf": [{"unless": {"memory": [{"npc": "heroine_01", "tag": "AN3_KEIGO"}]}, "lines": ["日文老師說，我的敬語變少了。以前我用太多。", "……我在練習不要那麼有距離。不知道是好事還是壞事。"]}], "note": "接大二上 A3-L2"}, {"id": "A4-L6", "if": {"stage": {"npc": "heroine_01", "min": "FAMILIAR"}}, "week": [12, 18], "lines": ["公法讀書會滿一年了。小語說要慶祝。", "……慶祝的方式是多讀一題。這是我提的。小語說我沒救了。"], "choices": [{"t": "「妳真的沒救了。」", "reply": "……謝謝。理由：這是稱讚。"}, {"t": "「我帶飲料。」", "reply": "好。十分鐘以內喝完。", "rel": {"comf": 1}}], "rel": {"fam": 2}, "note": "讀書會大一下第 12 週開始"}, {"id": "A4-L7", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "lines": ["大三要選交換的志願了。", "我第一次覺得，選一個地方，就是放下另外一個。"], "choices": [{"t": "「放下什麼？」", "reply": "……讀書會。家教。……還有一些人。我會回來，可是會錯過。", "rel": {"trust": 2}}, {"t": "「妳會選對的。」", "reply": "……沒有對的。只有理由寫得完整的。"}], "rel": {"fam": 2, "trust": 2}, "mem": "AN4_CHOOSING", "note": "大三上申請、大三下出發（主線 8；交換延畢照 AA_137 第 2 節，這裡不提延畢）"}, {"id": "A4-L8", "if": {"stage": {"npc": "heroine_01", "min": "FRIEND"}}, "week": [16, 18], "lines": ["暑假七月底回台中兩週。剩下的，要準備交換的申請。", "第一次，暑假排滿了。……我有一點想念沒排的那一年。"], "choices": [{"t": "「留一天給自己。」", "reply": "……好。理由欄寫：留白。", "rel": {"comf": 2}}, {"t": "「申請加油。」", "reply": "……嗯。寫完給你看。只看第一頁。"}], "rel": {"fam": 2, "comf": 1}, "mem": "AN4_SUMMER", "linesIf": [{"if": {"memory": [{"npc": "heroine_01", "tag": "AN2_SUMMER"}]}, "lines": ["暑假七月底回台中兩週。剩下的，要準備交換的申請。", "去年你說沒排也很好。……今年排滿了。我有一點想念去年。"]}], "note": "接大一下 A2-L8（第一次沒排的暑假）"}], "greet": {"base": ["早。今天的債各很重要。……每一堂都很重要。", "我剛家教完。學生今天沒有翻白眼。進步。", "（她把交換說明會的資料夾在手帳裡）……只是先收著。", "讀書會今天多讀一題。你要來嗎？", "霖澤館的冷氣今天很強。我帶了外套。理由：去年冷過。"], "when": [{"weekday": [4], "time": [19, 21], "location": ["wancai"], "t": "讀書會快開始了。今天小語帶了雞蛋糕。……我同意的。"}, {"week": [3, 6], "location": ["campus"], "t": "杜鵑花開了。……第二張，我拍了。"}, {"week": [8, 9], "t": "期中。手帳右欄：還可以。……我知道，不是進度。"}, {"location": ["library_hall", "library"], "weather": "rain", "t": "下雨了。我的傘在室友那裡。……她說會還。"}, {"week": [16, 18], "t": "期末了。我把交換的申請表印出來了。……先不寫。考完再寫。"}]}}, "heroine_03": {"steps": [{"id": "Y4-L1", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "week": [1, 18], "lines": ["過年店休三天。我帶阿姨去看海。", "她在沙灘上坐了一個小時，什麼都沒說。回來的路上，她說：明年還要。"], "choices": [{"t": "「阿姨開心嗎？」", "reply": "……嗯。她回來那天，湯煮得特別鹹。她開心的時候都這樣。"}, {"t": "「妳呢？」", "reply": "……我也開心。我的湯沒有變鹹。"}], "rel": {"fam": 2, "comf": 1}, "mem": "YT4_SEA_TRIP", "linesIf": [{"if": {"memory": [{"npc": "heroine_03", "tag": "YT3_SEA"}]}, "lines": ["過年，我們真的去看海了。", "阿姨在沙灘上坐了一個小時。回來的路上，她說：明年還要。"]}], "note": "接大二上 Y3-L8（想帶阿姨去看海）"}, {"id": "Y4-L2", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "lines": ["法服的記錄本，我寫到第三本了。", "我發現椅子擺成斜的，人比較敢講。……正對著，像在被問話。"], "choices": [{"t": "「妳自己發現的？」", "reply": "……嗯。看了很多次。"}, {"t": "「下次教我。」", "reply": "……好。先學倒水。"}], "rel": {"fam": 2}, "mem": "YT4_CHAIRS"}, {"id": "Y4-L3", "if": {"stage": {"npc": "heroine_03", "min": "ACQUAINTANCE"}}, "lines": ["我想做一個田野。……還不知道題目。", "老師說，題目會自己來找你。我說，那它要找得到麵店。"], "choices": [{"t": "「麵店本身就是題目。」", "reply": "……嗯。可能。……先不要跟阿姨說。"}, {"t": "「題目會來的。」", "reply": "……嗯。我在等。我很會等。"}], "rel": {"fam": 2, "trust": 1}, "note": "大三事件 14 準備（記下老客人的話＝她第一次做田野）、事件 15 的伏筆；不提租約"}, {"id": "Y4-L4", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "week": [8, 18], "lines": ["阿姨最近開始學記帳。用手機。", "她記錯了三次。我幫她改。她說我很囉嗦。"], "choices": [{"t": "「囉嗦是幫忙。」", "reply": "……嗯。我也這樣跟她說。她說：一樣囉嗦。"}, {"t": "「需要我幫忙嗎？」", "reply": "……不用。你陪我吃麵就好。"}], "rel": {"fam": 2, "comf": 1}, "note": "續約前的準備在背景（AA_11 事件 14「準備」）；**不說為什麼開始記帳**（租約是事件 8、9 的戲）。選項 2 的回答和事件 11 的「陪我吃麵就好」同方向，事件 11 之前或之後都說得通"}, {"id": "Y4-L5", "if": {"stage": {"npc": "heroine_03", "min": "FAMILIAR"}}, "lines": ["阿哲跟小語現在都坐同一桌。", "阿姨每次都多給他們一雙筷子。……不知道為什麼。"], "choices": [{"t": "「阿姨在祝福他們。」", "reply": "……嗯。阿姨的祝福都是用筷子。"}, {"t": "「他們會用嗎？」", "reply": "……不會。可是每次都收下。"}], "rel": {"fam": 2}}, {"id": "Y4-L6", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "lines": ["我媽說想來店裡幫忙。阿姨說不行。", "兩個人吵了一個晚上。……最後我媽負責剝蒜頭。"], "choices": [{"t": "「跟妳小時候一樣。」", "reply": "……嗯。她剝得比我慢。可是她說她剝得比較漂亮。", "rel": {"trust": 1}}, {"t": "「妳媽媽身體還好嗎？」", "reply": "……嗯。剝蒜頭可以。她很高興。"}], "rel": {"fam": 2, "trust": 2}, "mem": "YT4_MOM_GARLIC", "note": "回聲大一上 Y-L3（剝蒜頭）、大二上 Y3-L6（媽媽散步）；不寫病情"}, {"id": "Y4-L7", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "week": [16, 18], "lines": ["學姊畢業了。初談組現在是我在顧。", "……我把椅子都擺成斜的了。"], "choices": [{"t": "「妳會顧得很好。」", "reply": "……嗯。你說的，我記著。"}, {"t": "「學姊說了什麼？」", "reply": "……她說了很多。我只記得一句。不告訴你。"}], "rel": {"fam": 2, "trust": 2}, "mem": "YT4_INTAKE_LEAD", "note": "學姊大二下第 15 週畢業（6/5）；語彤接初談組長（交接包 v3 第 4 節）。**學姊的話不直接引用**（學姊是 BB-B 的人物）"}, {"id": "Y4-L8", "if": {"stage": {"npc": "heroine_03", "min": "FRIEND"}}, "week": [16, 18], "lines": ["暑假我要開始訪問老客人。阿姨說，客人的話比菜單還長。", "……第一個要訪問的，是每天點乾麵的那個阿伯。"], "choices": [{"t": "「我可以幫妳記。」", "reply": "……嗯。你字很醜。……好。", "rel": {"comf": 2}}, {"t": "「他會說什麼？」", "reply": "……不知道。所以要問。"}], "rel": {"fam": 2, "comf": 1}, "mem": "YT4_FIELDWORK", "note": "大三事件 14「語彤把老客人說的話記下來」的開始（背景）；不說是為了續約", "location": ["noodle", "campus", "library_hall", "library", "wenzhou"], "locTime": {"noodle": {"weekday": [2, 4], "time": [20, 20.5]}}}], "greet": {"base": ["……嗯。", "（她抱著第三本初談記錄本）……要買新的了。", "……阿姨今天換了新的湯勺。她說舊的會想念。", "……總圖今天冷氣好強。我帶了外套。", "……你也來了。"], "when": [{"weekday": [6], "time": [9, 12], "location": ["wancai"], "t": "（她把椅子擺成斜的）……先坐。要喝水嗎？"}, {"location": ["noodle"], "weekday": [2, 4], "time": [17.5, 20], "t": "……今天客人多。阿哲他們坐老位子。"}, {"location": ["library_hall", "library"], "weekday": [1, 3, 5], "time": [19, 21.5], "t": "（她在靠窗的位子，小聲）……嗯。"}, {"week": [8, 9], "t": "……期中。今天不顧店，念書。"}, {"weather": "rain", "t": "……下雨了。我帶了兩把。"}]}}}}, "kaiDorm": [{"id": "K-D1", "title": "一起打電動", "location": "dorm", "time": [21, 24], "weekday": [0, 1, 2, 3, 4], "perWeek": 1, "lines": ["所以 一場就好 你上路 我中路"], "choices": [{"t": "「一場就好。」", "advance": 1, "energy": -5, "rel": {"kai": {"fam": 3}}, "random": ["所以我們是天才", "是隊友的問題 不是我們的", "宿舍網路 我要告它 你們有教這個嗎"], "count": "KAI_GAMES"}, {"t": "「我要念書。」", "reply": "好 那我小聲", "narr": "（他沒有小聲。）"}]}, {"id": "K-D2", "title": "一場變三場", "if": {"flagNum": {"KAI_GAMES": {"min": 2}}}, "once": true, "location": "dorm", "time": [23, 24], "narr": "一場變三場，抬頭已經兩點。", "lines": ["所以 你明天第一堂幾點"], "choices": [{"t": "「九點十分。」", "reply": "所以是早八 在宿舍 九點以前都叫早八 還可以睡六個小時 很多了", "nextMorningEnergy": -10}, {"t": "「我去睡了。」", "reply": "好 我再一場"}]}, {"id": "K-D3", "title": "鍵盤聲", "location": "dorm", "time": [7, 8.5], "needs": "玩家今天第一堂在 9:10 以前（大一必修最早 9:10；宿舍說法叫「早八」，K-D2），且昨晚沒參加 K-D1（隨機 30%）", "narr": "阿凱的螢幕還亮著，他戴著耳機在打字，鍵盤聲很大。", "choices": [{"t": "「可以小聲一點嗎？」", "reply": "所以 我吵到你了 對不起 我換靜音的那把", "mem": "KAI_QUIET_KEYBOARD"}, {"t": "（什麼都不說，出門）", "inc": "KAI_FRICTION"}, {"t": "「你到底要不要睡？」", "goto": "K-D4"}]}, {"id": "K-D4", "title": "吵架", "when": "K-D3 選第三個，或 KAI_FRICTION 到 3", "lines": [{"who": "kai", "t": "所以 你現在是在念我嗎"}, {"who": "player", "t": "我只是想睡覺。"}, {"who": "kai", "t": "我也想啊 可是程式寫不完"}], "narr": "兩個人都不說話。他把燈關了，自己用手機的光繼續打字。", "set": "KAI_FIGHT", "effect": "之後兩天阿凱只說「嗯」，SMALLTALK 暫停；不影響其他人"}, {"id": "K-D5", "title": "和解的飲料", "if": {"flags": ["KAI_FIGHT"]}, "location": "dorm", "daysAfter": [1, 3], "narr": "桌上有一杯飲料，杯子上貼著一張便利貼：「所以 這是和解的飲料 不是賄賂」", "choices": [{"t": "（喝掉，說）「我也太兇了。」", "reply": "所以 我們訂一個規則 一點以後我戴耳機打字 你早八前一天我不開喇叭", "mem": "KAI_ROOM_RULES", "rel": {"kai": {"fam": 4, "trust": 3}}, "clear": "KAI_FIGHT"}, {"t": "（去買宵夜回來）", "reply": "所以 你也在和解 那我們兩個都和解了。所以 我們訂一個規則……", "mem": "KAI_ROOM_RULES", "rel": {"kai": {"fam": 4, "trust": 3}}, "clear": "KAI_FIGHT"}], "fallback": "沒去宿舍的話，第 4 天阿凱自己先說「所以 上次的事 是我不對」，照樣和好（KAI_ROOM_RULES、清 KAI_FIGHT）"}, {"id": "K-D6", "title": "室友模式", "if": {"memory": [{"npc": "kai", "tag": "KAI_ROOM_RULES"}]}, "once": true, "location": "dorm", "weekday": [0], "time": [20, 24], "lines": ["所以 我寫了一個小程式 會在一點的時候叫我戴耳機", "它叫「室友模式」"], "choices": [{"t": "「謝謝。」", "reply": "不客氣 它目前只會說「所以」", "rel": {"kai": {"fam": 2}}}]}], "bikeSeat": {"_comment": "腳踏車載妹墊（AA_137 第 5 節）：FAMILIAR 以上、約好同行才坐；學姊有伴侶時不坐、走在旁邊（walk）。可昕、以安、語彤、阿凱、阿哲的台詞在 AA_137／ladder_aa.json。", "heroine_02": {"min": "FAMILIAR", "on": "……我第一次坐別人的後座。不要笑。", "off": "謝謝。……你騎得比我想的穩。", "decline": "我走路就好。我喜歡看路邊的店。"}, "heroine_04": {"min": "FAMILIAR", "on": "欸不是，你的腳踏車本來就有後座墊？……好，出發。這不是問句。", "off": "再騎一圈。……騙你的。到了。", "decline": "我會暈車。腳踏車也會。……好啦是我還不熟你。"}, "classmate_peishan": {"min": "FAMILIAR", "on": "我可以問一個奇怪的問題嗎？……坐後座要抓哪裡？", "off": "好好玩。我小時候都坐我爸的機車後座送蛋餅。", "decline": "我走路！我走得很快，你看。"}, "heroine_05": {"min": "FAMILIAR", "on": "兩件事。一，我側坐，抓後面的架子。二，騎慢一點。……三，不要回頭。", "off": "到了。一，你騎得很穩。二，謝謝。三，……沒有三。", "decline": "我走路就好。你先騎，我跟得上。", "note": "D78（使用者 2026-10-16 01:12，經 LAWWW-B）：學姊也坐後座（側坐），有伴侶時一樣；朋友之間的分寸：抓後面的架子、不抓人"}}};
